        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_EMPADAO_VEGANO_ALHO_FRANCES + "', '<h3>Ingredientes:</h3><ul><li>3 alhos-franceses grandes fatiados</li><li>1 chávena de lentilhas vermelhas cozidas</li><li>800g de puré de batata (feito com bebida vegetal)</li><li>Noz-moscada, sal e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Estufe o alho-francês em azeite até murchar. Junte as lentilhas e tempere.</li><li><b>Montar:</b> Num pirex, coloque o recheio e cubra com o puré de batata.</li><li><b>Gratinar:</b> Pincele com azeite e leve ao forno até criar uma crosta dourada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CARIL_ABOBORA_MANTEIGA_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1/2 abóbora manteiga em cubos</li><li>2 chávenas de grão-de-bico cozido</li><li>1 lata de leite de coco</li><li>2 colheres de sopa de caril em pó</li><li>Gengibre, coentros e limão</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estufe a abóbora no leite de coco com o caril e gengibre ralado.</li><li><b>Grão:</b> Quando a abóbora estiver macia, junte o grão e deixe apurar 5 min.</li><li><b>Finalizar:</b> Adicione sumo de limão e coentros frescos. Sirva com arroz basmati.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_FEIJOADA_COUVE_LOMBARDA + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijão branco ou manteiga</li><li>1/2 couve lombarda em tiras</li><li>2 cenouras em rodelas</li><li>1 chouriço de soja</li><li>Cominhos, cebola, alho e tomate</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Refogue a cebola com alho e cominhos. Junte a couve e cenoura.</li><li><b>Estufar:</b> Adicione o feijão e o chouriço fatiado com um pouco de água.</li><li><b>Apurar:</b> Deixe cozinhar em lume brando até a couve estar bem tenra e o molho rico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_RISOTO_CEVADA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de cevada perlada (demolhada)</li><li>300g de cogumelos fatiados</li><li>Caldo de legumes caseiro quente</li><li>1 cebola, 100ml de vinho branco, levedura nutricional</li></ul><h3>Preparação:</h3><ol><li><b>Cevada:</b> Refogue a cebola, junte a cevada e o vinho. Deixe evaporar.</li><li><b>Cozinhar:</b> Adicione o caldo aos poucos, mexendo sempre, como um risoto.</li><li><b>Finalizar:</b> Junte os cogumelos salteados à parte e a levedura para cremosidade.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TOFU_LAGAREIRO_BATATA_MURRO + "', '<h3>Ingredientes:</h3><ul><li>400g de tofu firme em fatias grossas</li><li>12 batatas pequenas com casca</li><li>Muito alho (6-8 dentes)</li><li>Azeite virgem extra, louro e azeitonas</li></ul><h3>Preparação:</h3><ol><li><b>Batatas:</b> Coza as batatas com pele, escorra e dê um \"murro\" em cada uma.</li><li><b>Assar:</b> Disponha as batatas e o tofu num tabuleiro. Cubra com alho laminado e muito azeite.</li><li><b>Dourar:</b> Leve ao forno a 200°C por 20 min. Sirva com azeitonas pretas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MASSA_FORNO_ABOBORA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>300g de massa curta (ex: penne)</li><li>500g de abóbora assada e triturada</li><li>1/2 chávena de natas de caju</li><li>Folhas de sálvia fresca, pão ralado</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Misture o puré de abóbora com as natas de caju e sálvia picada.</li><li><b>Combinar:</b> Envolva a massa cozida no molho e coloque num tabuleiro.</li><li><b>Gratinar:</b> Cubra com pão ralado e mais folhas de sálvia. Leve ao forno a dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_LASANHA_COGUMELOS_CREME_AVELA + "', '<h3>Ingredientes:</h3><ul><li>Folhas de lasanha integral</li><li>500g de cogumelos salteados</li><li><b>Bechamel:</b> 500ml de leite de avelã, 2 colheres de sopa de farinha e manteiga de avelã pura</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Prepare um bechamel usando leite de avelã e junte 1 colher de manteiga de avelã no final.</li><li><b>Montar:</b> Camadas de massa, cogumelos e o molho de avelã.</li><li><b>Assar:</b> Cubra com o restante molho e leve ao forno por 30 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ALMONDEGAS_BOLOTA_MOLHO_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de bolota (ou puré de grão com farinha de bolota)</li><li>1 chávena de grão-de-bico cozido e triturado</li><li>1 cebola pequena e 2 dentes de alho picados</li><li>500ml de molho de tomate rústico caseiro</li><li>1 colher de chá de ervas da Provença</li><li>Pão ralado integral q.b. (se necessário)</li><li>Azeite virgem extra, sal e pimenta</li></ul><h3>Preparação:</h3><ol><li><b>Almôndegas:</b> Numa taça, misture o puré de grão, a farinha de bolota, o alho e as ervas. Tempere com sal e pimenta. Se a massa estiver muito húmida, junte um pouco de pão ralado até conseguir moldar.</li><li><b>Formar:</b> Molde pequenas bolas e coloque-as num tabuleiro com papel vegetal. Pincele com azeite.</li><li><b>Assar:</b> Leve ao forno a 200°C por 15-20 minutos até estarem firmes e com uma crosta leve.</li><li><b>Estufar:</b> Coloque as almôndegas no molho de tomate bem quente e deixe cozinhar em lume brando por mais 10 minutos para absorverem o sabor.</li><li><b>Servir:</b> Acompanhe com massa integral, esparguete de curgete ou um puré de batata-doce.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_QUICHE_SEM_MASSA_GRELOS_TOFU + "', '<h3>Ingredientes:</h3><ul><li>1 molho grande de grelos de nabo cozidos e bem escorridos</li><li>300g de tofu firme esmagado</li><li>4 colheres de sopa de farinha de grão-de-bico</li><li>1/2 chávena de água (ou bebida de soja sem açúcar)</li><li>1 colher de chá de cúrcuma e 1/2 de sal negro (Kala Namak)</li><li>1 dente de alho picado e azeite</li><li>Pinhões para decorar</li></ul><h3>Preparação:</h3><ol><li><b>Base Líquida:</b> Bata a farinha de grão com a água, a cúrcuma e o sal negro até obter um creme liso (substituto do ovo).</li><li><b>Misturar:</b> Numa taça larga, envolva os grelos picados, o tofu esmagado e o alho picado. Junte a base líquida e misture bem.</li><li><b>Forma:</b> Verta o preparado para uma forma de tarte previamente untada com azeite. Alise a superfície e salpique com os pinhões.</li><li><b>Assar:</b> Leve ao forno a 190°C por cerca de 25-30 minutos até a quiche estar bem firme ao toque e dourada por cima.</li><li><b>Finalizar:</b> Deixe arrefecer 5-10 min antes de desenformar e servir com uma salada de tomate.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_XAREM_ALGARVIO_AMEIJOA_VEG + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de milho amarela (fina)</li><li>4 chávenas de caldo vegetal com sabor a mar (coza uma folha de alga Nori no caldo)</li><li>250g de cogumelos Ostra (Pleurotus) rasgados em tiras</li><li>2 dentes de alho picados</li><li>Bastantes coentros frescos e sumo de 1/2 limão</li><li>Azeite virgem extra, sal e pimenta branca</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar Papas:</b> Leve o caldo (sem a alga) ao lume. Quando ferver, adicione a farinha de milho em chuva, mexendo sempre com uma vara de arames. Cozinhe em lume brando por 15-20 min até estar cremoso.</li><li><b>Saltear ''Ameijoas'':</b> Numa frigideira com azeite, salteie os cogumelos com o alho e uma pitada de sal até dourarem e estarem bem secos.</li><li><b>Finalizar Xarém:</b> Junte os cogumelos salteados ao xarém. Adicione bastantes coentros frescos picados e o sumo de limão.</li><li><b>Servir:</b> Retifique os temperos e sirva quente numa taça rústica, decorado com mais coentros.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_GNOCCHI_CASTANHA_MANTEIGA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>500g de gnocchi de batata (ou artesanal de castanha)</li><li>1 chávena de castanhas cozidas (descascadas e partidas ao meio)</li><li>3 colheres de sopa de manteiga vegetal de boa qualidade</li><li>12-15 folhas de sálvia fresca</li><li>Pimenta preta moída na hora e flor de sal</li><li>Opcional: lascas de queijo vegan curado</li></ul><h3>Preparação:</h3><ol><li><b>Gnocchi:</b> Coza o gnocchi em água abundante com sal até subirem à superfície. Escorra e reserve.</li><li><b>Aromatizar:</b> Numa frigideira larga, derreta a manteiga vegetal até começar a espumar. Junte as folhas de sálvia e deixe fritar até estarem crocantes (cuidado para não queimar).</li><li><b>Saltear:</b> Adicione as castanhas à manteiga de sálvia para aquecerem e ganharem sabor.</li><li><b>Envolver:</b> Junte o gnocchi à frigideira e envolva delicadamente em lume médio até os gnocchis ficarem levemente dourados.</li><li><b>Servir:</b> Tempere com flor de sal e pimenta preta. Sirva de imediato, decorado com as folhas de sálvia crocantes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CALDEIRADA_VEGAN_PALMITO_RAIZES + "', '<h3>Ingredientes:</h3><ul><li>1 frasco de palmito em rodelas (escorrido)</li><li>2 batatas médias e 1 nabo (em rodelas de 1cm)</li><li>1 cebola grande e 1 pimento verde (em rodelas)</li><li>2 tomates maduros picados</li><li>2 dentes de alho laminados</li><li>1/2 chávena de vinho branco e 1 colher de chá de colorau</li><li>Azeite virgem extra, sal e pimenta</li><li>Ramos de salsa ou hortelã fresca</li></ul><h3>Preparação:</h3><ol><li><b>Camadas:</b> Num tacho largo, faça camadas começando pela cebola e alho, depois o pimento, as batatas, o nabo e, por fim, o palmito.</li><li><b>Tempero:</b> Regue cada camada com um pouco de sal, pimenta e colorau.</li><li><b>Líquidos:</b> Adicione o tomate picado por cima e regue tudo com o vinho branco e um fio generoso de azeite.</li><li><b>Estufar:</b> Tape o tacho hermeticamente e cozinhe em lume brando por 30-35 minutos. Não mexa para não desfazer os legumes; abane o tacho ocasionalmente.</li><li><b>Finalizar:</b> Verifique se a batata está tenra. Decore com salsa ou hortelã e sirva com fatias de pão rústico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ROLO_LENTILHAS_RECHEADO_ALHO + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de lentilhas castanhas cozidas (bem escorridas)</li><li>1 chávena de nozes nacionais picadas grosseiramente</li><li>1 chávena de pão ralado integral</li><li><b>Recheio:</b> 2 alhos-franceses pequenos e 1 cenoura ralada salteados</li><li>1 colher de sopa de molho de soja e 1 colher de chá de cominhos</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Triture as lentilhas com as nozes, o pão ralado, o molho de soja e os cominhos até obter uma massa moldável (pode manter alguns pedaços de noz).</li><li><b>Estender:</b> Sobre uma folha de papel vegetal untada, estenda a massa formando um retângulo com cerca de 1,5 cm de espessura.</li><li><b>Rechear:</b> Disponha o salteado de alho-francês e cenoura sobre a massa.</li><li><b>Enrolar:</b> Com a ajuda do papel vegetal, enrole a massa firmemente para formar um rolo. Feche bem as extremidades.</li><li><b>Assar:</b> Leve ao forno a 200°C por 35-40 minutos, pincelando com um pouco de azeite ou molho de soja a meio do tempo, até estar dourado e firme.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BURRITO_QUENTE_FEIJAO_PRETO_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>4 tortilhas grandes (trigo integral)</li><li>2 chávenas de feijão preto estufado (com pouco caldo)</li><li>2 chávenas de abóbora manteiga assada em cubos</li><li>2 chávenas de rúcula fresca</li><li><b>Molho:</b> 1/2 chávena de iogurte de soja natural, sumo de 1/2 lima e sal</li><li>Azeite e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Preparar Molho:</b> Misture o iogurte com a lima e o sal. Reserve no frio.</li><li><b>Montar:</b> No centro de cada tortilha, disponha uma porção de feijão quente, cubos de abóbora e um punhado de rúcula. Regue com uma colher do molho de iogurte.</li><li><b>Fechar:</b> Dobre as extremidades laterais para o centro e enrole a tortilha de baixo para cima com firmeza.</li><li><b>Grelhar:</b> Aqueça uma frigideira antiaderente ou prensa de sanduíches. Grelhe os burritos por 1-2 minutos de cada lado até a tortilha estar dourada e o recheio bem quente. Sirva cortado ao meio.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TACOS_COGUMELOS_PLEUROTUS_CEBOLA + "', '<h3>Ingredientes:</h3><ul><li>8 mini tortilhas de milho (ou tacos rígidos)</li><li>400g de cogumelos Pleurotus (desfiados com um garfo)</li><li>1 cebola roxa grande em meias-luas</li><li>2 dentes de alho picados</li><li>1 colher de chá de colorau e uma pitada de chili</li><li>Sumo de 1 lima e coentros frescos picados</li><li>Azeite virgem extra e sal</li></ul><h3>Preparação:</h3><ol><li><b>Saltear Cogumelos:</b> Numa frigideira bem quente com azeite, salteie os cogumelos Pleurotus desfiados com o alho, o colorau e o chili. Deixe cozinhar até estarem dourados e com as bordas estaladiças. Reserve.</li><li><b>Preparar Cebola:</b> Use a cebola roxa crua para frescura ou salteie-a rapidamente se preferir mais suave.</li><li><b>Montar:</b> Aqueça as tortilhas. Recheie cada uma com os cogumelos e a cebola.</li><li><b>Finalizar:</b> Regue generosamente com sumo de lima fresco e polvilhe com coentros. Sirva de imediato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_STIR_FRY_TEMPEH_REPOLHO_OUTONO + "', '<h3>Ingredientes:</h3><ul><li>250g de tempeh (em tiras finas)</li><li>1/2 repolho coração (fatiado muito fino/ripado)</li><li>1 cenoura grande ralada</li><li>2 dentes de alho e 2cm de gengibre fresco ralado</li><li><b>Molho:</b> 3 colheres de sopa de molho de soja, 1 de óleo de sésamo e 1 de sementes de sésamo torradas</li><li>Azeite ou óleo de coco</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar Tempeh:</b> Numa frigideira larga ou wok, grelhe o tempeh com um fio de azeite e o gengibre até estar bem dourado e crocante. Retire e reserve.</li><li><b>Saltear Vegetais:</b> Na mesma frigideira, junte o repolho e a cenoura. Salteie em lume alto por apenas 2-3 minutos para que os vegetais murchem mas mantenham a cor e a textura crocante.</li><li><b>Combinar:</b> Volte a colocar o tempeh na frigideira.</li><li><b>Finalizar:</b> Regue com o molho de soja e o óleo de sésamo. Envolva tudo rapidamente em lume forte. Sirva polvilhado com as sementes de sésamo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_COUSCOUS_MARROQUINO_GRAO_PASSAS + "', '<h3>Ingredientes:</h3><ul><li>1 e 1/2 chávena de cuscuz de trigo fino</li><li>1 e 1/2 chávena de caldo de legumes quente</li><li>1 e 1/2 chávena de grão-de-bico cozido</li><li>1/4 chávena de passas de uva sultanas</li><li>1/4 chávena de miolo de noz picado</li><li>1 colher de chá de canela e 1 de cominhos</li><li>Um punhado de hortelã fresca picada</li><li>Azeite virgem extra e sal</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Coloque o cuscuz numa taça com as especiarias (canela e cominhos) e as passas. Verta o caldo a ferver por cima, tape e aguarde 5 min.</li><li><b>Soltar:</b> Use um garfo para separar os grãos do cuscuz.</li><li><b>Misturar:</b> Junte o grão-de-bico, as nozes picadas e regue com um fio generoso de azeite. Envolva bem.</li><li><b>Servir:</b> Polvilhe com a hortelã fresca picada no momento para um aroma intenso. Pode ser servido quente ou como salada fria.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_FEIJAO_FRADE_ESTUFADO_COUVE_GALEGA + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas (500g) de feijão frade cozido</li><li>1 molho grande de couve galega cortada muito fina (ripada)</li><li>3 dentes de alho picados</li><li>1 cebola pequena picada</li><li>1 folha de louro</li><li>Azeite virgem extra em abundância, sal e pimenta</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Num tacho largo, refogue a cebola, o alho e o louro num fundo generoso de azeite até a cebola estar translúcida.</li><li><b>Saltear:</b> Junte a couve galega ripada e envolva no refogado. Deixe cozinhar em lume médio por 5-8 min, mexendo sempre, até a couve estar bem macia mas com cor verde.</li><li><b>Estufar:</b> Adicione o feijão frade e um pingo da água da sua cozedura. Tempere com sal e pimenta.</li><li><b>Finalizar:</b> Deixe estufar por 3-5 minutos para os sabores ligarem. Sirva bem quente, idealmente acompanhado com uma fatia de broa de milho.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MARMITA_FORNO_BATATA_DOCE_BROCOLOS + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce de polpa laranja média (em cubos de 2cm)</li><li>1 brócolos médio (separado em floretes pequenos)</li><li>1/2 chávena de cajus ou sementes de girassol</li><li>2 dentes de alho esmagados</li><li><b>Tempero:</b> Azeite, sal, pimenta e 1 colher de chá de tomilho seco</li></ul><h3>Preparação:</h3><ol><li><b>Assar Batata:</b> Num tabuleiro de forno, coloque os cubos de batata-doce. Regue com azeite, sal e tomilho. Leve ao forno a 200°C por 15 minutos.</li><li><b>Adicionar Brócolos:</b> Retire o tabuleiro, junte os brócolos e o alho esmagado. Envolva bem nos sucos do tabuleiro.</li><li><b>Assar Final:</b> Leve ao forno por mais 10-15 minutos até os brócolos estarem ''al dente'' e as bordas levemente tostadas.</li><li><b>Toque Crocante:</b> Nos últimos 5 minutos, salpique com as sementes ou cajus para tostarem.</li><li><b>Servir:</b> Perfeito para levar na marmita, pois mantém o sabor frio ou aquecido.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CANELONES_RECHEADOS_ESPINAFRE_RICOTA + "', '<h3>Ingredientes:</h3><ul><li>12 tubos de canelones (que não precisem de pré-cozedura)</li><li>500g de espinafres frescos (salteados e picados)</li><li>250g de ricota de amêndoa ou tofu cremoso</li><li>500ml de molho de tomate rústico bem fluido</li><li>Queijo vegan para gratinar e noz-moscada</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Numa taça, misture os espinafres bem picados e escorridos com a ricota vegetal. Tempere com sal, pimenta e uma pitada generosa de noz-moscada.</li><li><b>Rechear:</b> Encha cada tubo de canelone com esta mistura, usando uma colher pequena ou saco de pasteleiro.</li><li><b>Montar:</b> Coloque um fundo de molho de tomate num pirex. Disponha os canelones e cubra totalmente com o restante molho (o molho deve ser abundante para cozer a massa).</li><li><b>Assar:</b> Polvilhe com o queijo vegetal e leve ao forno a 180°C por 30-35 minutos, coberto com folha de alumínio nos primeiros 20 min.</li><li><b>Gratinar:</b> Retire o papel e deixe dourar a crosta. Sirva quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CHILI_VEGAN_LENTILHAS_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>1 e 1/2 chávena de lentilhas castanhas secas (ou 2 latas cozidas)</li><li>2 chávenas de abóbora menina cortada em cubos minúsculos (1cm)</li><li>1 cebola, 2 dentes de alho e 1 pimento verde picados</li><li>1 lata (400g) de tomate em cubos</li><li>1 colher de chá de cominhos, 1 de colorau e chili em pó a gosto</li><li>Azeite, sal e coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Refogue a cebola, o alho e o pimento em azeite. Junte as especiarias e deixe fritar por 1 min.</li><li><b>Estufar:</b> Adicione a abóbora e as lentilhas. Junte o tomate e cubra com água ou caldo de legumes.</li><li><b>Apurar:</b> Cozinhe em lume brando por 20-30 min (se as lentilhas forem secas) até o molho estar bem espesso e os ingredientes macios.</li><li><b>Servir:</b> Sirva bem quente numa taça, decorado com coentros picados e acompanhado com arroz branco ou triângulos de tortilha (nachos) integrais.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MIGAS_ALENTEJANAS_COGUMELOS_SILVESTRES + "', '<h3>Ingredientes:</h3><ul><li>400g de pão rústico alentejano duro (de 2-3 dias)</li><li>300g de cogumelos silvestres (ou mistura de Shiitake e Paris)</li><li>5 dentes de alho esmagados</li><li>Azeite virgem extra de boa qualidade (em abundância)</li><li>Sal, pimenta e um pequeno molho de salsa fresca</li></ul><h3>Preparação:</h3><ol><li><b>Pão:</b> Corte o pão em pedaços pequenos. Coloque numa taça e regue ligeiramente com água quente apenas para humedecer as côdeas (não ensopar).</li><li><b>Saltear:</b> Numa frigideira larga, doure os alhos em bastante azeite. Junte os cogumelos fatiados e salteie em lume alto até estarem bem tostados. Reserve os cogumelos.</li><li><b>Migas:</b> Na mesma frigideira, junte o pão e vá mexendo e batendo com a colher de pau, adicionando pingos de água se necessário, até o pão formar uma massa ligada e dourada por fora.</li><li><b>Misturar:</b> Envolva os cogumelos reservados e a salsa picada nas migas.</li><li><b>Servir:</b> Molde um rolo ou sirva rústico. É o prato de conforto ideal para um dia frio de outono.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESPAGUETE_INTEGRAL_ALHO_AZEITE_NOCES + "', '<h3>Ingredientes:</h3><ul><li>250g de esparguete de trigo integral</li><li>4 dentes de alho laminados</li><li>1/2 chávena de miolo de noz picado grosseiramente</li><li>Um punhado de salsa fresca picada</li><li>Azeite virgem extra, sal e flocos de malagueta</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza o esparguete em água abundante com sal até estar al dente.</li><li><b>Aromatizar:</b> Enquanto a massa coze, coloque o azeite e o alho laminado numa frigideira fria. Ligue o lume médio e deixe o alho dourar suavemente para aromatizar o azeite.</li><li><b>Tostar:</b> Junte as nozes à frigideira e deixe fritar por 1 minuto com o alho e a malagueta.</li><li><b>Finalizar:</b> Adicione a massa escorrida diretamente na frigideira com um pingo da água da cozedura. Envolva bem, junte a salsa e sirva de imediato com um fio de azeite em cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TORTILHA_FORNO_LEGUMES_OUTONO + "', '<h3>Ingredientes:</h3><ul><li>3 batatas médias em rodelas finas</li><li>1 alho-francês (rodelas) e 1 cenoura (meias-luas)</li><li>1 chávena de farinha de grão-de-bico batida com 1 chávena de água</li><li>1 colher de chá de cúrcuma e sal negro</li><li>Azeite e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Salteie levemente as batatas, o alho-francês e a cenoura em azeite numa frigideira até estarem quase tenros.</li><li><b>Massa:</b> Numa taça, misture a farinha de grão com a água, a cúrcuma e o sal até obter um creme liso.</li><li><b>Combinar:</b> Misture os legumes na massa de grão e verta tudo para um pirex de forno redondo (ou frigideira que vá ao forno).</li><li><b>Assar:</b> Leve ao forno a 180°C por cerca de 20 minutos até a tortilha estar firme no centro e as bordas douradas.</li><li><b>Servir:</b> Deixe repousar 5 min, polvilhe com salsa e corte em fatias como uma omelete tradicional.</li></ol>');");
        // ==========================================
// JANTARES - OUTUBRO (TODOS OS 31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BATATA_DOCE_RECHEADA + "', '<h3>Ingredientes:</h3><ul><li>1 batata-doce média (assada inteira)</li><li>1 chávena de lentilhas castanhas estufadas</li><li>1/2 abacate maduro</li><li>Sumo de limão, coentros e sementes de sésamo</li></ul><h3>Preparação:</h3><ol><li><b>Batata:</b> Abra a batata-doce assada a meio e esmague ligeiramente o interior com um garfo.</li><li><b>Rechear:</b> Coloque as lentilhas estufadas quentes no centro da batata.</li><li><b>Finalizar:</b> Disponha fatias de abacate por cima, regue com limão e polvilhe com coentros e sementes de sésamo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_POLENTA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de polenta (sêmola de milho)</li><li>300g de cogumelos variados</li><li>2 dentes de alho, tomilho fresco</li><li>1 colher de sopa de levedura nutricional e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Polenta:</b> Coza a polenta em 3 chávenas de água com sal até ficar cremosa. Junte a levedura no final.</li><li><b>Saltear:</b> Salteie os cogumelos com alho e tomilho em azeite até dourarem.</li><li><b>Servir:</b> Coloque a polenta numa taça e cubra com os cogumelos aromáticos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_EMPADAO_COUVE_FLOR + "', '<h3>Ingredientes:</h3><ul><li>1 couve-flor média em puré</li><li>200g de seitan picado</li><li>1 cebola, 1 cenoura, polpa de tomate</li><li>Noz-moscada, sal e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Refogue o seitan com a cebola, cenoura ralada e tomate.</li><li><b>Puré:</b> Coza a couve-flor e triture com um pouco de bebida vegetal e noz-moscada.</li><li><b>Assar:</b> Num pirex, coloque o seitan e cubra com o puré. Leve ao forno a dourar por 15 min.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TOFU_CROSTA_AVELA + "', '<h3>Ingredientes:</h3><ul><li>250g de tofu firme</li><li>1/2 chávena de avelãs picadas grosseiramente</li><li>2 colheres de sopa de mostarda Dijon</li><li>1 colher de sopa de mel de arroz</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Seque bem o tofu e corte em fatias grossas.</li><li><b>Pincelar:</b> Misture a mostarda com o mel e barre o tofu.</li><li><b>Crosta:</b> Pressione o tofu nas avelãs picadas até cobrir bem.</li><li><b>Grelhar:</b> Leve à frigideira antiaderente (ou forno) até a crosta estar crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ABOBORA_FORNO_TAHINI + "', '<h3>Ingredientes:</h3><ul><li>1/2 abóbora manteiga fatiada</li><li><b>Molho:</b> 2 colheres de sopa de tahini, sumo de 1/2 limão, 1 dente de alho esmagado</li><li>Salsa picada e sementes de romã</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse as fatias de abóbora com azeite e sal a 200°C por 25 min.</li><li><b>Molho:</b> Misture os ingredientes do molho com um pouco de água até ficar fluido.</li><li><b>Finalizar:</b> Regue a abóbora quente com o molho e decore com salsa e romã.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_FRITTATA_ALHO_FRANCES + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de grão batida com 1 chávena de água</li><li>2 alhos-franceses fatiados</li><li>Cúrcuma, sal negro (kala namak) e pimenta</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Salteie o alho-francês em azeite até estar bem macio.</li><li><b>Misturar:</b> Junte o alho-francês à massa de farinha de grão temperada.</li><li><b>Cozinhar:</b> Deite numa frigideira antiaderente, tape e cozinhe em lume brando por 8 min de cada lado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_COGUMELOS_PORTOBELLO_RECHEADOS + "', '<h3>Ingredientes:</h3><ul><li>2 cogumelos Portobello gigantes</li><li>1/2 chávena de quinoa cozida</li><li>1/4 chávena de espinafres picados, nozes picadas</li><li>Alho, azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Retire os pés dos cogumelos e pique-os. Misture com a quinoa, espinafres e nozes.</li><li><b>Rechear:</b> Coloque a mistura nas abas dos cogumelos.</li><li><b>Assar:</b> Regue com um fio de azeite e leve ao forno a 190°C por 20 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESTUFADO_LENTILHAS_COUVE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas vermelhas</li><li>2 chávenas de couve lombarda em tiras</li><li>Cebola, alho, tomate e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe as lentilhas no refogado de cebola e tomate com cominhos.</li><li><b>Couve:</b> Quando as lentilhas estiverem quase prontas, junte a couve e deixe murchar.</li><li><b>Servir:</b> O prato deve ficar cremoso e bem apurado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_COUVE_CORACAO_RECHEADA + "', '<h3>Ingredientes:</h3><ul><li>4 folhas grandes de couve coração</li><li>1/2 chávena de arroz integral cozido</li><li>1/2 chávena de tofu esmagado, passas e pinhões</li></ul><h3>Preparação:</h3><ol><li><b>Escaldar:</b> Passe as folhas de couve por água a ferver para ficarem maleáveis.</li><li><b>Recheio:</b> Misture o arroz com o tofu e frutos secos.</li><li><b>Enrolar:</b> Coloque o recheio na folha, dobre e enrole.</li><li><b>Vapor:</b> Cozinhe as trouxas ao vapor por 10 minutos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_SALADA_QUENTE_KALE + "', '<h3>Ingredientes:</h3><ul><li>1 molho de couve kale picada</li><li>1 maçã Reineta em cubos</li><li>1/2 chávena de nozes e bagas de goji</li><li>Vinagrete de limão e mel de arroz</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Passe a kale rapidamente por uma frigideira quente com azeite (2 min).</li><li><b>Misturar:</b> Numa taça, junte a kale morna, a maçã, nozes e bagas.</li><li><b>Temperar:</b> Verta o vinagrete e envolva bem. Sirva como jantar leve.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_STROGANOFF_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>400g de cogumelos frescos fatiados</li><li>1 cebola picada, 1 colher de sopa de mostarda</li><li>1 pacote de natas de soja (ou de aveia)</li><li>Páprica fumada e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Doure a cebola e junte os cogumelos até secarem a água.</li><li><b>Finalizar:</b> Junte a mostarda, a páprica e as natas. Deixe engrossar 2 min.</li><li><b>Servir:</b> Polvilhe com salsa e acompanhe com arroz branco solto.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_QUICHE_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa quebrada integral</li><li>2 alhos-franceses grandes</li><li>1 pacote de natas de soja, 2 colheres de amido de milho</li><li>Noz-moscada e pimenta</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Salteie o alho-francês em rodelas até amolecer.</li><li><b>Base:</b> Misture as natas com o amido e temperos. Junte o alho-francês.</li><li><b>Assar:</b> Verta sobre a massa e leve ao forno a 180°C por 25-30 min.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CARIL_RECONFORTANTE_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>Chuchu, cenoura e batata-doce em cubos</li><li>1 lata de leite de coco, 2 colheres de sopa de caril</li><li>Gengibre fresco e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estufe os legumes no leite de coco com o caril e o gengibre.</li><li><b>Apurar:</b> Deixe ferver em lume brando até os legumes estarem tenros.</li><li><b>Finalizar:</b> Sirva com muitos coentros picados por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MIGAS_GRELOS_BROA + "', '<h3>Ingredientes:</h3><ul><li>1 molho de grelos cozidos e picados</li><li>300g de broa de milho esfarelada</li><li>4 dentes de alho, azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Alho:</b> Doure o alho picado em bastante azeite.</li><li><b>Saltear:</b> Junte os grelos e envolva. Adicione a broa de milho.</li><li><b>Misturar:</b> Vá mexendo em lume alto até a broa absorver o azeite e ficar crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_GNOCCHI_ABOBORA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>500g de gnocchi de batata</li><li>1 chávena de puré de abóbora assada</li><li>Folhas de sálvia fresca, azeite e nozes picadas</li></ul><h3>Preparação:</h3><ol><li><b>Sálvia:</b> Frite as folhas de sálvia em azeite até estarem estaladiças. Retire.</li><li><b>Misturar:</b> Na mesma frigideira, junte o puré de abóbora e o gnocchi cozido.</li><li><b>Finalizar:</b> Envolva bem, junte a sálvia e as nozes. Sirva quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BIFE_COUVE_FLOR + "', '<h3>Ingredientes:</h3><ul><li>1 couve-flor grande (cortada em fatias de 2cm)</li><li><b>Tempero:</b> Azeite, alho em pó, páprica, sal e pimenta</li><li>Húmus para acompanhar</li></ul><h3>Preparação:</h3><ol><li><b>Pincelar:</b> Barre as fatias de couve-flor com a mistura de temperos.</li><li><b>Grelhar:</b> Leve à chapa bem quente (ou forno a 200°C) até estar macia e tostada.</li><li><b>Servir:</b> Acompanhe com uma base de húmus cremoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BRUSCHETTA_QUENTE_PATE + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de centeio</li><li>4 colheres de sopa de paté de cogumelos (ou azeitona)</li><li>Folhas de espinafre frescas e tomate seco</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Toste o pão. Barre generosamente com o paté.</li><li><b>Montar:</b> Disponha os espinafres e o tomate seco por cima.</li><li><b>Aquecer:</b> Leve ao forno apenas 3 min para amornar os sabores.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TEMPEH_GRELHADO_BROCOLOS + "', '<h3>Ingredientes:</h3><ul><li>200g de tempeh marinado em soja e limão</li><li>1 brócolos médio em floretes</li><li>Sementes de sésamo e molho teriyaki (opcional)</li></ul><h3>Preparação:</h3><ol><li><b>Vapor:</b> Coza os brócolos ao vapor por 4 minutos.</li><li><b>Grelhar:</b> Grelhe o tempeh na chapa até estar bem dourado de ambos os lados.</li><li><b>Finalizar:</b> Sirva o tempeh com os brócolos, polvilhado com sésamo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PATANISCAS_LEGUMES_ARROZ + "', '<h3>Ingredientes:</h3><ul><li>1 cenoura e 1 curgete raladas</li><li>1 chávena de farinha de trigo, 1/2 de água gaseificada</li><li>1/2 chávena de arroz cozido para acompanhar</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha, água e legumes ralados até formar um polme espesso.</li><li><b>Fritar:</b> Frite colheradas do polme em azeite quente até dourarem.</li><li><b>Servir:</b> Acompanhe com uma pequena porção de arroz de tomate ou simples.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESTUFADO_FEIJAO_BRANCO + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijão branco cozido</li><li>1 molho de espinafres frescos</li><li>Polpa de tomate, cebola e alho</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Faça um refogado simples. Junte o feijão e um pouco de água.</li><li><b>Espinafres:</b> Quando ferver, adicione os espinafres e deixe murchar.</li><li><b>Finalizar:</b> Sirva quente com uma fatia de pão torrado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PASTEL_FORNO_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>Massa de empada vegan (de compra ou caseira)</li><li>Recheio de lentilhas vermelhas bem apuradas e secas</li><li>Azeitonas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Coloque o recheio frio no centro de discos de massa.</li><li><b>Fechar:</b> Dobre ao meio e pressione as bordas com um garfo.</li><li><b>Assar:</b> Leve ao forno a 200°C por 15-20 min até dourarem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_SARRACENO_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de trigo sarraceno cozido</li><li>200g de cogumelos fatiados</li><li>Salsa, alho e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Salteie os cogumelos com alho em azeite abundante.</li><li><b>Misturar:</b> Envolva o trigo sarraceno nos cogumelos quentes.</li><li><b>Finalizar:</b> Polvilhe com muita salsa fresca picada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_QUINOA_OUTONO_FORNO + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de quinoa cozida</li><li>Cubos de abóbora e batata-doce assados</li><li>Canela, noz-moscada e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Combinar:</b> Misture a quinoa com os legumes assados.</li><li><b>Assar:</b> Coloque num pirex, tempere com as especiarias e leve ao forno 10 min.</li><li><b>Servir:</b> Prato quente e saciante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_TARTE_FOLHADA_BETERRABA + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa folhada vegetal</li><li>2 beterrabas cozidas fatiadas</li><li>Alecrim e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Disponha as fatias de beterraba sobre a massa folhada.</li><li><b>Assar:</b> Tempere com alecrim e azeite. Leve ao forno até a massa folhar e dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_MASSA_CREMOSA_CAJU + "', '<h3>Ingredientes:</h3><ul><li>250g de massa espirais</li><li>1/2 chávena de manteiga de caju diluída em água</li><li>Levedura nutricional e manjericão</li></ul><h3>Preparação:</h3><ol><li><b>Molho:</b> Misture a manteiga de caju com água e levedura até criar um creme.</li><li><b>Misturar:</b> Envolva a massa cozida no creme morno.</li><li><b>Finalizar:</b> Decore com folhas de manjericão fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_BURRITO_BOWL_NOITE + "', '<h3>Ingredientes:</h3><ul><li>Arroz integral, feijão preto, milho</li><li>Tomate, abacate e coentros</li><li>Molho de lima</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Organize os ingredientes em secções numa taça larga.</li><li><b>Temperar:</b> Regue com sumo de lima e azeite. Um jantar colorido e fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_CREPE_SALGADO_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1 crepe de farinha de grão-de-bico</li><li>Espinafres e cogumelos salteados</li><li>Húmus de beterraba</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Barre o crepe com húmus, coloque os legumes e enrole.</li><li><b>Aquecer:</b> Passe rapidamente pela frigideira para servir morno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_ESPETADAS_TOFU_LEGUMES + "', '<h3>Ingredientes:</h3><ul><li>Cubos de tofu firme, pimentos e cebola roxa</li><li>Molho de soja e gengibre</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Alterne os ingredientes nos espetos.</li><li><b>Grelhar:</b> Cozinhe na chapa pincelando com o molho até caramelizar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_PAPA_AVEIA_SALGADA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de aveia</li><li>1 chávena de caldo de legumes</li><li>1 colher de sopa de sementes de girassol e cebolinho</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a aveia no caldo até estar bem cremosa.</li><li><b>Servir:</b> Finalize com as sementes e o cebolinho fresco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_WRAP_FORNO_FEIJAO + "', '<h3>Ingredientes:</h3><ul><li>1 wrap integral</li><li>1/2 chávena de feijão chili (vegetariano)</li><li>Queijo vegetal para derreter</li></ul><h3>Preparação:</h3><ol><li><b>Enrolar:</b> Recheie o wrap com o feijão e coloque num tabuleiro.</li><li><b>Assar:</b> Cubra com queijo e leve ao forno 10 min até gratinar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_OUT_XAREM_NOITE_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de milho</li><li>100g de cogumelos salteados com alho</li><li>Coentros frescos</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Faça o xarém simples.</li><li><b>Servir:</b> Disponha os cogumelos por cima e polvilhe com coentros.</li></ol>');");

        // ==========================================
// PEQUENOS-ALMOÇOS - NOVEMBRO (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PAPA_AVEIA_TANGERINA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de flocos de aveia</li><li>1 chávena de bebida de arroz (ou aveia)</li><li>2 tangerinas suculentas</li><li>1 colher de chá de sementes de linhaça moída</li><li>Canela em pó</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a aveia na bebida de arroz com a linhaça em lume brando até ficar cremosa.</li><li><b>Fruta:</b> Descasque as tangerinas e retire os gomos (remova as grainhas se necessário).</li><li><b>Servir:</b> Deite as papas numa taça, disponha os gomos de tangerina por cima e polvilhe com canela.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TORRADA_DOCE_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de trigo sarraceno (ou centeio)</li><li>1/2 chávena de puré de abóbora assada</li><li>1 colher de sopa de manteiga de amêndoa</li><li>Mel de arroz ou ágave, e canela</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Toste as fatias de pão até ficarem crocantes.</li><li><b>Base:</b> Misture o puré de abóbora com a manteiga de amêndoa e uma pitada de canela.</li><li><b>Barrar:</b> Espalhe generosamente sobre o pão quente e finalize com um fio de mel de arroz.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PANQUECA_CASTANHA_CACAU + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de farinha de castanha</li><li>1 ovo (ou substituto de linhaça)</li><li>1 colher de chá de cacau puro em pó</li><li>1/2 chávena de água ou bebida vegetal</li><li>Pepitas de chocolate negro</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha de castanha, o cacau e o ovo. Junte o líquido gradualmente até ter um polme macio.</li><li><b>Cozinhar:</b> Verta porções numa frigideira antiaderente. Junte algumas pepitas por cima.</li><li><b>Virar:</b> Quando secar as bordas, vire e cozinhe mais 1 min. Sirva com fruta fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BOLO_CANECA_MARMELO + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de farinha de aveia</li><li>1 colher de sopa de puré de marmelo caseiro (sem açúcar)</li><li>1 colher de sopa de iogurte vegetal</li><li>1 colher de chá de fermento, canela</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte todos os ingredientes numa caneca grande e mexa bem com um garfo.</li><li><b>Cozedura:</b> Leve ao microondas na potência máxima por 90 segundos.</li><li><b>Servir:</b> Deixe arrefecer um pouco e coma diretamente da caneca ou desenforme num prato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_WAFFLE_BATATA_DOCE + "', '<h3>Ingredientes:</h3><ul><li>100g de batata-doce cozida e esmagada</li><li>2 colheres de sopa de farinha de arroz</li><li>1/2 chávena de bebida de amêndoa</li><li>Canela, gengibre e 1 colher de mel de cana</li></ul><h3>Preparação:</h3><ol><li><b>Bater:</b> Misture a batata-doce com a farinha, a bebida vegetal e as especiarias até ter uma massa homogénea.</li><li><b>Tostar:</b> Unte a máquina de waffles e deite a massa. Cozinhe até estar bem dourada e firme.</li><li><b>Finalizar:</b> Sirva quente com um fio de mel de cana (típico da Madeira).</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PUDIM_CHIA_DIOSPIRO + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de sementes de chia</li><li>1 chávena de bebida de aveia</li><li>1 diospiro bem maduro (polpa mole)</li><li>Amêndoas laminadas</li></ul><h3>Preparação:</h3><ol><li><b>Chia:</b> Misture a chia na bebida vegetal e deixe no frigorífico durante a noite (ou pelo menos 30 min).</li><li><b>Diospiro:</b> Retire a polpa do diospiro com uma colher.</li><li><b>Montagem:</b> Coloque o pudim de chia numa taça, cubra com a polpa de diospiro e as amêndoas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TOFU_MEXIDO_GRELOS + "', '<h3>Ingredientes:</h3><ul><li>150g de tofu firme esmagado</li><li>1 chávena de grelos de nabo picados</li><li>2 dentes de alho, azeite</li><li>Cúrcuma, sal preto e pimenta</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Refogue o alho em azeite, junte os grelos picados e deixe murchar.</li><li><b>Cozinhar:</b> Adicione o tofu esmagado e a cúrcuma. Mexa bem por 5 min em lume médio.</li><li><b>Finalizar:</b> Tempere com o sal negro (sabor a ovo) e sirva com pão de milho torrado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_CREPE_ESPELTA_MACA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de farinha de espelta integral</li><li>1/2 chávena de água</li><li>1 maçã pequena fatiada muito fina</li><li>Canela e 1 colher de manteiga de noz</li></ul><h3>Preparação:</h3><ol><li><b>Frigideira:</b> Faça um crepe fino com a massa de espelta e água numa frigideira antiaderente.</li><li><b>Rechear:</b> Coloque as fatias de maçã no centro do crepe ainda quente e polvilhe com canela.</li><li><b>Dobrar:</b> Dobre o crepe e sirva com uma colher de manteiga de noz por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_MUFFIN_AVEIA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de aveia, 1 colher de sopa de linhaça moída</li><li>1/2 chávena de nozes picadas</li><li>1 banana madura esmagada</li><li>1/2 chávena de bebida vegetal e fermento</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture todos os ingredientes até obter uma massa espessa.</li><li><b>Formas:</b> Verta para formas de queque (muffins).</li><li><b>Assar:</b> Leve ao forno a 180°C por 18-20 minutos até estarem dourados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BATIDO_QUENTE_CHOCOLATE + "', '<h3>Ingredientes:</h3><ul><li>1 e 1/2 chávena de bebida de soja (ou avelã)</li><li>1 colher de sopa de cacau puro</li><li>1 tâmara Medjool (para adoçar)</li><li>1 pau de canela e 1 pitada de pimenta caiena</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Aqueça a bebida de soja com o pau de canela (não deixe ferver).</li><li><b>Triturar:</b> Retire a canela e coloque o líquido no liquidificador com o cacau e a tâmara.</li><li><b>Servir:</b> Processe bem até ficar espumoso e sirva numa caneca grande com a pimenta por cima.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PAPA_CENTEIO_PASSA_UVA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de centeio integral</li><li>1 chávena de água</li><li>2 colheres de sopa de uvas passas escuras</li><li>Raspa de limão e canela</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a farinha de centeio na água com a raspa de limão, mexendo sempre para não agarrar.</li><li><b>Passas:</b> Junte as passas a meio da cozedura para que hidratem e fiquem doces.</li><li><b>Finalizar:</b> Sirva quente numa taça e polvilhe generosamente com canela em pó.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TORRADA_CREME_CAJU_ANIS + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão integral de sementes</li><li>2 colheres de sopa de creme de caju natural</li><li>Sementes de anis (erva-doce) e um fio de ágave</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Prepare as torradas de pão de sementes.</li><li><b>Barrar:</b> Espalhe o creme de caju sobre o pão quente.</li><li><b>Aromatizar:</b> Polvilhe com as sementes de anis e termine com um fio leve de xarope de ágave.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_GRANOLA_INVERNO_LEITE + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de granola de outono (com nozes e canela)</li><li>1 chávena de bebida de aveia morna</li><li>1 colher de chá de sementes de abóbora</li><li>Fatias de maçã Reineta</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque a granola numa taça de pequeno-almoço.</li><li><b>Aquecer:</b> Verta a bebida de aveia morna por cima da granola.</li><li><b>Fruta:</b> Disponha as fatias de maçã e as sementes de abóbora no topo. Coma antes que a granola amoleça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_SCONES_BOLOTA_ERVA_DOCE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de bolota (ou mistura com trigo integral)</li><li>1/2 chávena de água quente</li><li>1 colher de chá de erva-doce moída</li><li>1 colher de chá de fermento</li></ul><h3>Preparação:</h3><ol><li><b>Moldar:</b> Misture os ingredientes até formar uma massa pesada mas moldável.</li><li><b>Formar:</b> Faça pequenas bolas achatadas e coloque num tabuleiro forrado.</li><li><b>Assar:</b> Leve ao forno a 200°C por 12-15 min até estarem firmes por fora e fofos por dentro.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BRUSCHETTA_PASTINACA_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia grande de pão de Mafra</li><li>1 pastinaca média</li><li>Azeite virgem extra, sal e tomilho</li><li>Húmus para barrar</li></ul><h3>Preparação:</h3><ol><li><b>Pastinaca:</b> Corte a pastinaca em fatias e asse no forno com azeite e tomilho até caramelizar.</li><li><b>Torrar:</b> Toste o pão e barre com uma camada de húmus.</li><li><b>Montar:</b> Coloque as fatias de pastinaca quente por cima e regue com um fio de azeite cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PAPA_PAINCO_PERA_COZIDA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de flocos de painço</li><li>1 pera rocha cozida com canela</li><li>1 chávena de bebida de arroz e avelã</li><li>Noz-moscada</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza os flocos de painço na bebida vegetal com uma pitada de noz-moscada.</li><li><b>Fruta:</b> Esmague a pera cozida e junte-a às papas cremosas.</li><li><b>Servir:</b> Coma morno. O painço é um cereal muito nutritivo e sem glúten.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TORRADA_HUMUS_PIMENTO + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de cereais</li><li>4 colheres de sopa de húmus de grão</li><li>1/2 pimento vermelho assado em tiras</li><li>Orégãos secos</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Toste as fatias de pão.</li><li><b>Montar:</b> Barre generosamente com o húmus e disponha as tiras de pimento assado.</li><li><b>Finalizar:</b> Polvilhe com orégãos e sirva como um pequeno-almoço salgado e proteico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BATIDO_DIOSPIRO_AVEIA + "', '<h3>Ingredientes:</h3><ul><li>1 diospiro de roer (persimon) grande</li><li>2 colheres de sopa de aveia em flocos</li><li>1/2 chávena de água fresca</li><li>1 rodela de gengibre e 1 colher de sementes de cânhamo</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Coloque o diospiro descascado, a aveia, o gengibre e as sementes no liquidificador.</li><li><b>Processar:</b> Junte a água e triture na velocidade máxima até obter um creme sedoso.</li><li><b>Beber:</b> Sirva de imediato para aproveitar todas as vitaminas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_GALETTE_INTEGRAL_MACA + "', '<h3>Ingredientes:</h3><ul><li>100g de farinha integral de trigo ou espelta</li><li>Água q.b. para formar massa</li><li>1 maçã fatiada finamente</li><li>Canela e 1 colher de mel de arroz</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Forme uma bola de massa com farinha e água. Estenda num círculo rústico.</li><li><b>Recheio:</b> Disponha as fatias de maçã no centro, deixando as bordas livres.</li><li><b>Assar:</b> Dobre as bordas sobre a maçã e leve ao forno a 190°C por 20 min até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TACA_KEFIR_ROMA_AVELA + "', '<h3>Ingredientes:</h3><ul><li>1 taça de kefir de coco ou iogurte natural</li><li>1/2 chávena de bagos de romã frescos</li><li>1 mão cheia de avelãs torradas picadas</li><li>Hortelã fresca</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Coloque o kefir na taça de servir.</li><li><b>Fruta:</b> Adicione os bagos de romã (antioxidantes) e as avelãs crocantes.</li><li><b>Finalizar:</b> Decore com folhas de hortelã para um toque de frescura matinal.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BARRINHA_AVEIA_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de aveia, 2 colheres de geleia de arroz</li><li>1 colher de sopa de sementes de sésamo e girassol</li><li>1/2 maçã ralada para humedecer</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva todos os ingredientes até formar uma massa compacta e pegajosa.</li><li><b>Forma:</b> Pressione num tabuleiro pequeno com 2cm de altura.</li><li><b>Assar:</b> Leve ao forno a 170°C por 15 min. Corte em retângulos enquanto ainda morno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_OVO_FORNO_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>1 ovo biológico</li><li>1 grande punhado de espinafres frescos</li><li>1 colher de sopa de leite de coco</li><li>Sal, pimenta e noz-moscada</li></ul><h3>Preparação:</h3><ol><li><b>Cama:</b> Num pequeno ramequim, coloque os espinafres com o leite de coco e noz-moscada.</li><li><b>Assar:</b> Parta o ovo por cima. Leve ao forno a 200°C por 8-10 minutos até a clara estar firme.</li><li><b>Servir:</b> Acompanhe com uma fatia de pão de centeio torrado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_SMOOTHIE_BOWL_KALE_PERA + "', '<h3>Ingredientes:</h3><ul><li>1 folha de couve kale (sem o talo)</li><li>1 pera madura</li><li>1/2 banana congelada</li><li>1/2 chávena de bebida de arroz</li><li>Topping: Granola e sementes de chia</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Bata a kale, a pera, a banana e a bebida vegetal no liquidificador até ficar muito cremoso.</li><li><b>Servir:</b> Verta para uma taça funda.</li><li><b>Decorar:</b> Adicione a granola e as sementes por cima para dar textura. Coma com colher.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PAPA_SARRACENO_CHOCOLATE + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de trigo sarraceno</li><li>1 chávena de água</li><li>1 colher de chá de cacau puro</li><li>Fatias de banana e avelãs picadas</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a farinha de sarraceno na água mexendo sempre por 5 min.</li><li><b>Chocolate:</b> Retire do lume e misture o cacau até estar bem integrado.</li><li><b>Finalizar:</b> Sirva com a banana e as avelãs por cima. Um pequeno-almoço quente e energético.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TORRADA_REQUEIJAO_DOCE + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de mistura torradas</li><li>1/2 chávena de requeijão de amêndoa</li><li>2 colheres de compota de abóbora caseira</li><li>Amêndoas laminadas</li></ul><h3>Preparação:</h3><ol><li><b>Tostar:</b> Prepare as fatias de pão bem crocantes.</li><li><b>Barrar:</b> Coloque uma camada generosa de requeijão vegetal.</li><li><b>Finalizar:</b> Cubra com a compota de abóbora e polvilhe com amêndoas para dar crocância.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BOLACHAS_INTEGRAIS_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de aveia, 1/2 de farinha integral</li><li>1/2 chávena de nozes picadas, 1 banana esmagada</li><li>1 colher de sopa de óleo de coco</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture todos os ingredientes até obter uma pasta moldável.</li><li><b>Moldar:</b> Forme bolachas pequenas e achatadas.</li><li><b>Assar:</b> Leve ao forno a 180°C por 15 min até dourarem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_TACA_IOGURTE_MACA_CANELA + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte vegetal natural</li><li>1/2 maçã Reineta em cubos</li><li>Canela em pó e sementes de abóbora</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Coloque o iogurte numa taça.</li><li><b>Fruta:</b> Adicione a maçã fresca e polvilhe generosamente com canela.</li><li><b>Crocante:</b> Termine com as sementes de abóbora.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_PUDIM_LINHACA_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de linhaça moída</li><li>2 colheres de puré de abóbora assada</li><li>1/2 chávena de bebida vegetal morna</li><li>Cravinho moído</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Misture a linhaça na bebida morna e espere 10 min.</li><li><b>Sabor:</b> Envolva o puré de abóbora e o cravinho.</li><li><b>Servir:</b> Coma à colher como um pudim reconfortante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_WRAP_QUENTE_BANANA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 wrap integral</li><li>1 colher de manteiga de amêndoa</li><li>1/2 banana e nozes picadas</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Barre o wrap com a manteiga, coloque a banana e as nozes.</li><li><b>Aquecer:</b> Enrole e leve à frigideira 1 min de cada lado para servir quente e crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_PEQ_BRUSCHETTA_COGUMELOS_ALHO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão rústico torrada</li><li>150g de cogumelos fatiados</li><li>Alho, azeite e salsa fresca</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os cogumelos em azeite com muito alho e salsa até dourarem.</li><li><b>Servir:</b> Disponha sobre o pão e regue com o suco do salteado.</li></ol>');");

        // ==========================================
// ALMOÇOS - NOVEMBRO (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_FEIJOADA_FEIJOCA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijoca cozida</li><li>400g de cogumelos frescos fatiados</li><li>1 cebola grande, 3 dentes de alho, 2 cenouras</li><li>Polpa de tomate, louro, cominhos e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Faça um refogado com cebola, alho, louro e cenoura em cubos.</li><li><b>Cogumelos:</b> Junte os cogumelos e deixe cozinhar até reduzirem. Adicione o tomate.</li><li><b>Apurar:</b> Junte a feijoca e um pouco de água da cozedura. Tempere com cominhos e sal.</li><li><b>Finalizar:</b> Deixe apurar em lume brando por 15 min. Sirva com arroz branco.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ASSADO_SÃO_MARTINHO + "', '<h3>Ingredientes:</h3><ul><li>300g de seitan fatiado</li><li>1 chávena de castanhas cozidas e descascadas</li><li>Batatinhas novas e cebolinhas</li><li>Vinho branco, alecrim, alho e pimentão doce</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Disponha o seitan, as batatas, as cebolinhas e as castanhas num tabuleiro.</li><li><b>Temperar:</b> Regue com azeite, vinho branco e tempere com alho, sal e alecrim.</li><li><b>Forno:</b> Leve ao forno a 200°C por 30-40 min até as batatas estarem douradas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_RANCHO_VEGANO_GRÃO + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de grão-de-bico cozido</li><li>1 chávena de massa de cotovelos</li><li>1 batata grande, 1 cenoura, 1/4 de couve lombarda</li><li>Colorau, cebola, alho e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza a batata, cenoura e couve lombarda em água com sal.</li><li><b>Massa:</b> Junte la massa quando os legumes estiverem quase cozidos.</li><li><b>Finalizar:</b> Adicione o grão e um refogado de alho com colorau por cima. Sirva com o caldo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ARROZ_GRELOS_PATANISCAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz carolino</li><li>1 molho de grelos picados</li><li><b>Pataniscas:</b> 1 cenoura ralada, 1 chávena de farinha, salsa e cebola picada</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Arroz:</b> Coza o arroz com os grelos em água abundante (proporção 1:3).</li><li><b>Pataniscas:</b> Faça um polme com a farinha, água, legumes e frite colheradas em azeite.</li><li><b>Servir:</b> Acompanhe o arroz de grelos bem húmido com as pataniscas estaladiças.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ESTUFADO_LENTILHAS_CASTANHAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas castanhas</li><li>1/2 chávena de castanhas em pedaços</li><li>1 alho-francês e 1 cenoura</li><li>100ml de vinho tinto, louro e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Salteie o alho-francês e a cenoura. Junte as lentilhas e castanhas.</li><li><b>Líquidos:</b> Adicione o vinho tinto e água quente. Tempere com sal e louro.</li><li><b>Estufar:</b> Deixe cozinhar em lume brando até as lentilhas estarem macias e o molho reduzido.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ARROZ_FORNO_ABOBORA_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz agulha</li><li>2 chávenas de abóbora em cubos</li><li>1 chávena de grão cozido</li><li>Açafrão, cravinho e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Num pirex, envolva o arroz cru, a abóbora, o grão e o açafrão.</li><li><b>Assar:</b> Cubra com 2 e 1/2 chávenas de água a ferver e tape com papel alumínio.</li><li><b>Finalizar:</b> Leve ao forno por 20 min até o arroz estar solto e a abóbora macia.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_EMPADAO_SOJA_PURE_CASTANHA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de soja fina hidratada</li><li><b>Puré:</b> 500g de castanhas cozidas e trituradas com leite vegetal</li><li>Cebola, alho e polpa de tomate</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Estufe a soja com um refogado de cebola e tomate até estar saborosa.</li><li><b>Montar:</b> Coloque a soja num pirex e cubra com o puré de castanha cremoso.</li><li><b>Assar:</b> Leve ao forno a 200°C por 15 min até dourar a superfície.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_CARIL_QUENTE_GRAO_BATATA + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de grão-de-bico cozido</li><li>2 batatas grandes em cubos</li><li>1 lata de leite de coco, 2 colheres de sopa de caril</li><li>Gengibre fresco e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a batata no leite de coco com o caril e gengibre.</li><li><b>Grão:</b> Junte o grão quando a batata estiver quase pronta.</li><li><b>Finalizar:</b> Deixe apurar o molho e sirva com muitos coentros frescos picados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_MASSA_FORNO_ABOBORA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>300g de massa curta</li><li>500g de abóbora assada em puré</li><li>Folhas de sálvia fresca</li><li>Natas de aveia e queijo vegan para gratinar</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva a massa cozida no puré de abóbora e natas.</li><li><b>Aromatizar:</b> Junte as folhas de sálvia picadas e coloque num tabuleiro.</li><li><b>Gratinar:</b> Cubra com o queijo vegetal e leve ao forno até estar bem quente e dourado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_TOFU_LAGAREIRO_BATATA_MURRO + "', '<h3>Ingredientes:</h3><ul><li>300g de tofu firme</li><li>12 batatas pequenas</li><li>Muito azeite, alho laminado e louro</li><li>Azeitonas pretas</li></ul><h3>Preparação:</h3><ol><li><b>Batatas:</b> Coza as batatas com pele, dê-lhes um murro e coloque no tabuleiro.</li><li><b>Tofu:</b> Junte o tofu em fatias grossas. Cubra com alho e azeite abundante.</li><li><b>Assar:</b> Leve ao forno por 20 min. Sirva com azeitonas pretas e salsa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_RISOTO_CEVADA_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de cevada perlada</li><li>300g de cogumelos variados</li><li>Caldo de legumes quente, vinho branco e cebola</li><li>Tomilho fresco</li></ul><h3>Preparação:</h3><ol><li><b>Cevada:</b> Refogue a cebola, junte a cevada e o vinho. Vá deitando o caldo aos poucos.</li><li><b>Cogumelos:</b> Salteie os cogumelos à parte com alho e tomilho.</li><li><b>Finalizar:</b> Quando a cevada estiver macia, junte os cogumelos e envolva bem.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_LASANHA_LENTILHAS_LOMBARDA + "', '<h3>Ingredientes:</h3><ul><li>Folhas de lasanha integral</li><li>Lentilhas estufadas com tomate</li><li>Folhas de couve lombarda escaldadas</li><li>Bechamel de soja</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Alterne camadas de massa, lentilhas e folhas de couve lombarda.</li><li><b>Cobertura:</b> Termine com o molho bechamel.</li><li><b>Assar:</b> Leve ao forno a 180°C por 30 min até a massa estar cozida.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ALMONDEGAS_BOLOTA_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>Almôndegas de farinha de bolota (ou grão)</li><li>500ml de molho de tomate caseiro</li><li>Páprica e manjericão</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Coloque as almôndegas no molho de tomate fervente.</li><li><b>Cozinhar:</b> Deixe cozinhar em lume brando por 15 min para tomarem o sabor.</li><li><b>Servir:</b> Acompanhe com esparguete integral ou puré de batata.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_TARTE_RUSTICA_GRELOS_TOFU + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa quebrada</li><li>1 molho de grelos salteados com alho</li><li>200g de tofu esfarelado e temperado</li><li>Pinhas e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Espalhe os grelos e o tofu sobre a massa.</li><li><b>Finalizar:</b> Salpique com pinhões e um fio de azeite.</li><li><b>Assar:</b> Leve ao forno por 20 min até a massa estar estaladiça.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_COZIDO_LEGUMES_ENCHIDOS_VEG + "', '<h3>Ingredientes:</h3><ul><li>Batata, nabo, cenoura, couve portuguesa</li><li>Farinheira e chouriço vegan</li><li>Grão-de-bico cozido e arroz de alho</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve os legumes e enchidos a cozer em água com sal.</li><li><b>Arroz:</b> Use o caldo da cozedura para fazer um arroz de alho saboroso.</li><li><b>Servir:</b> Disponha tudo numa travessa e regue com azeite cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_GNOCCHI_CASTANHA_MANTEIGA + "', '<h3>Ingredientes:</h3><ul><li>400g de gnocchi de batata</li><li>1 chávena de castanhas cozidas</li><li>Manteiga vegetal e folhas de sálvia</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Doure as castanhas e a sálvia na manteiga vegetal.</li><li><b>Misturar:</b> Junte o gnocchi cozido e envolva delicadamente.</li><li><b>Servir:</b> Prato de conforto ideal para os dias frios de Novembro.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_CALDEIRADA_VEGAN_RAIZES + "', '<h3>Ingredientes:</h3><ul><li>Rodelas de batata, nabo, cenoura e pastinaca</li><li>Cebola, pimento, tomate e alho</li><li>Vinho branco e pimentão doce</li></ul><h3>Preparação:</h3><ol><li><b>Camadas:</b> Disponha os legumes em camadas num tacho largo.</li><li><b>Líquidos:</b> Regue com vinho branco, azeite e polpa de tomate.</li><li><b>Estufar:</b> Tape o tacho e deixe cozinhar em lume brando por 30 min sem mexer.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ROLO_LENTILHAS_RECHEADO + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de lentilhas trituradas</li><li>1/2 chávena de nozes, 1/2 de pão ralado</li><li>Recheio: Alho-francês, cenoura e espinafres</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Misture as lentilhas com nozes e pão ralado até moldar.</li><li><b>Moldar:</b> Estenda a massa, coloque o recheio de legumes salteados e enrole.</li><li><b>Assar:</b> Leve ao forno por 30 min pincelando com azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_BURRITO_FEIJAO_PRETO_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>4 tortilhas grandes</li><li>2 chávenas de feijão preto</li><li>1 chávena de puré de abóbora</li><li>Cominhos e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Barre as tortilhas com a abóbora e o feijão.</li><li><b>Fechar:</b> Enrole bem e aqueça numa frigideira até estarem crocantes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_TACOS_COGUMELOS_PLEUROTUS + "', '<h3>Ingredientes:</h3><ul><li>8 tortilhas de milho</li><li>400g de Pleurotus desfiados</li><li>Cebola roxa, lima e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os cogumelos com alho até estarem dourados.</li><li><b>Servir:</b> Recheie as tortilhas e finalize com gotas de lima fresca.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_STIR_FRY_TEMPEH_REPOLHO + "', '<h3>Ingredientes:</h3><ul><li>200g de tempeh em cubos</li><li>1/2 repolho fatiado fino</li><li>Molho de soja e gengibre</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Doure o tempeh no wok. Junte o repolho e salteie por 2 min.</li><li><b>Finalizar:</b> Tempere com soja e sirva com arroz integral.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_COUSCOUS_GRAO_PASSAS_NOZ + "', '<h3>Ingredientes:</h3><ul><li>Cuscuz, grão-de-bico</li><li>Passas de uva, nozes e hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Cubra o cuscuz com caldo quente.</li><li><b>Misturar:</b> Junte os restantes ingredientes e solte com um garfo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_FEIJAO_FRADE_COUVE_GALEGA + "', '<h3>Ingredientes:</h3><ul><li>Feijão frade cozido</li><li>Couve galega fatiada</li><li>Alho e azeite abundante</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe a couve em azeite com alho.</li><li><b>Misturar:</b> Junte o feijão frade e envolva por 3 min.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_MARMITA_BATATA_DOCE_BROCOLOS + "', '<h3>Ingredientes:</h3><ul><li>Batata-doce, brócolos</li><li>Sementes de girassol</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Cozinhe os legumes no forno com azeite.</li><li><b>Finalizar:</b> Sirva numa taça com as sementes tostadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_CANELONES_ESPINAFRE_RICOTA + "', '<h3>Ingredientes:</h3><ul><li>Canelones, espinafres</li><li>Ricota de amêndoa, tomate</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Encha os canelones com os espinafres e ricota.</li><li><b>Assar:</b> Cubra com molho de tomate e leve ao forno por 30 min.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_CHILI_VEGAN_LENTILHAS_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>Lentilhas castanhas, abóbora em cubos</li><li>Tomate, chili e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe tudo em lume brando até estar bem apurado.</li><li><b>Servir:</b> Acompanhe com arroz basmati.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_MIGAS_ALENTEJANAS_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>400g de pão rústico alentejano duro (de 2-3 dias)</li><li>300g de cogumelos variados (Pleurotus ou Paris) fatiados</li><li>4 dentes de alho grandes esmagados</li><li>1 colher de chá de pimentão doce (páprica)</li><li>1/2 chávena de azeite virgem extra</li><li>Um molho de salsa fresca picada</li><li>Sal e pimenta preta q.b.</li></ul><h3>Preparação:</h3><ol><li><b>Pão:</b> Corte o pão em fatias finas ou pedaços pequenos. Coloque numa taça e regue levemente com água quente e sal, apenas para humedecer (não deve ficar ensopado).</li><li><b>Saltear Cogumelos:</b> Numa frigideira larga, aqueça o azeite com metade do alho. Salteie os cogumelos em lume alto até estarem bem dourados. Tempere com sal e pimenta e reserve.</li><li><b>Migas:</b> Na mesma frigideira, junte o restante alho e o pimentão doce. Adicione o pão humedecido e vá mexendo e batendo com uma colher de pau em lume médio.</li><li><b>Finalizar:</b> Continue a mexer até o pão formar uma massa ligada e começar a dourar por fora. Envolva os cogumelos reservados e a salsa picada.</li><li><b>Servir:</b> Molde um rolo rústico e sirva bem quente, decorado com raminhos de salsa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_ESPAGUETE_ALHO_AZEITE_NOZ + "', '<h3>Ingredientes:</h3><ul><li>250g de esparguete de trigo integral</li><li>1/2 chávena de miolo de noz picado grosseiramente</li><li>4 dentes de alho laminados finamente</li><li>1/2 chávena de azeite virgem extra</li><li>1 colher de chá de flocos de malagueta (opcional)</li><li>Salsa fresca picada e sal grosso</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza o esparguete em água abundante com sal até estar al dente. Reserve meia caneca da água da cozedura.</li><li><b>Infusão:</b> Numa frigideira fria, junte o azeite, o alho e os flocos de malagueta. Ligue o lume médio e deixe o alho começar a borbulhar e a dourar levemente para libertar o aroma.</li><li><b>Tostar Nozes:</b> Adicione as nozes picadas à frigideira e deixe fritar por 1 minuto, mexendo sempre para não queimar.</li><li><b>Emulsionar:</b> Junte a massa escorrida à frigideira e verta um pouco da água da cozedura reservada. Envolva vigorosamente em lume alto por 1 min para criar um molho cremoso.</li><li><b>Servir:</b> Finalize com a salsa picada e um fio de azeite em cru. Consuma de imediato.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_TORTILHA_FORNO_LEGUMES_OUT + "', '<h3>Ingredientes:</h3><ul><li>2 batatas médias e 1 cenoura (em rodelas finas)</li><li>1 alho-porro grande (em meias-luas)</li><li>1 chávena de floretes de brócolos pequenos</li><li>1 e 1/2 chávena de farinha de grão-de-bico</li><li>1 e 1/2 chávena de água</li><li>1 colher de chá de cúrcuma e uma pitada de sal negro (Kala Namak)</li><li>Azeite virgem extra e pimenta</li></ul><h3>Preparação:</h3><ol><li><b>Refogar Legumes:</b> Numa frigideira que possa ir ao forno (ou tabuleiro), salteie a batata, a cenoura e o alho-porro em azeite até estarem tenros. Junte os brócolos nos últimos 3 min.</li><li><b>Massa:</b> Numa taça, misture a farinha de grão com a água, a cúrcuma, o sal negro e a pimenta até obter um creme sem grumos.</li><li><b>Combinar:</b> Verta o creme de grão sobre os vegetais salteados na frigideira, garantindo que ficam bem distribuídos.</li><li><b>Assar:</b> Leve ao forno a 180°C por cerca de 15-20 minutos até o topo estar firme e as bordas levemente douradas.</li><li><b>Finalizar:</b> Deixe repousar 5 minutos para firmar antes de cortar em fatias como uma omelete rústica.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_ALM_QUICHE_SEM_MASSA_GRELOS + "', '<h3>Ingredientes:</h3><ul><li>1 molho grande de grelos de nabo cozidos e picados</li><li>300g de tofu firme (esmagado com um garfo)</li><li>200ml de natas de soja ou aveia</li><li>2 colheres de sopa de amido de milho (maizena)</li><li>1 cebola pequena e 2 dentes de alho picados</li><li>Noz-moscada, sal e pimenta preta</li><li>Azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Salteie a cebola e o alho em azeite. Junte os grelos picados (bem escorridos) e deixe saltear por 2 min para perderem a humidade excessiva.</li><li><b>Creme:</b> No liquidificador, triture o tofu com as natas vegetais, o amido de milho e os temperos até obter um creme aveludado e espesso.</li><li><b>Misturar:</b> Numa taça, envolva os grelos no creme de tofu e natas.</li><li><b>Assar:</b> Deite a mistura numa forma de tarte (previamente untada com azeite). Leve ao forno a 190°C por 30-35 minutos até estar bem dourada e firme ao toque.</li><li><b>Servir:</b> Deixe arrefecer um pouco antes de cortar. Acompanha bem com uma salada rústica de beterraba.</li></ol>');");

        // ==========================================
// JANTARES - NOVEMBRO (TODOS OS 30 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_SEITAN_SAN_MARTINHO + "', '<h3>Ingredientes:</h3><ul><li>250g de seitan em cubos</li><li>1/2 chávena de castanhas assadas</li><li>1 cebola, 2 dentes de alho, louro</li><li>100ml de vinho branco, azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Salteie o seitan em azeite com alho e louro até dourar.</li><li><b>Castanhas:</b> Junte as castanhas (já assadas ou cozidas) e envolva.</li><li><b>Apurar:</b> Regue com o vinho branco e deixe reduzir em lume brando por 5 min. Sirva quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_FEIJOADA_FEIJOCAS + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijocas cozidas</li><li>1 cenoura, 1 alho-francês</li><li>Polpa de tomate, cominhos, louro</li><li>Azeite virgem extra e sal</li></ul><h3>Preparação:</h3><ol><li><b>Refogar:</b> Faça um refogado com os vegetais picados em azeite.</li><li><b>Estufar:</b> Junte o tomate, o feijão e um pouco de água.</li><li><b>Finalizar:</b> Deixe apurar bem até o feijão estar cremoso e o molho encorpado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_CEVADOTTO_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de cevada perlada</li><li>200g de cogumelos frescos</li><li>1 cebola, caldo de legumes quente</li><li>Azeite e salsa fresca</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Refogue a cebola, junte a cevada e vá deitando o caldo aos poucos, mexendo sempre.</li><li><b>Finalizar:</b> Quando a cevada estiver tenra, junte os cogumelos salteados e salsa picada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_GRATINADO_BATATA_NABO + "', '<h3>Ingredientes:</h3><ul><li>2 batatas médias, 1 nabo grande</li><li>1 pacote de natas de soja (200ml)</li><li>Alho em pó, noz-moscada, sal</li></ul><h3>Preparação:</h3><ol><li><b>Dispor:</b> Corte a batata e o nabo em fatias muito finas. Alterne camadas num pirex.</li><li><b>Cobertura:</b> Regue com as natas temperadas com noz-moscada e alho.</li><li><b>Assar:</b> Leve ao forno a 180°C por 30 min até estar dourado e os legumes tenros.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_TOFU_FUMADO_GRELOS + "', '<h3>Ingredientes:</h3><ul><li>100 g de tofu fumado, grelos</li><li>Azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Vapor:</b> Coza os grelos ao vapor por 5 minutos.</li><li><b>Saltear:</b> Numa frigideira com azeite, doure o alho e o tofu fumado.</li><li><b>Finalizar:</b> Junte os grelos e envolva bem. Sirva com uma fatia de pão de milho.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_HAMBURGUER_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de lentilhas vermelhas cozidas (escorridas)</li><li>1/2 chávena de aveia em flocos finos</li><li>Cominhos, cebola picada, salsa</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Esmague as lentilhas e misture com a aveia e temperos até formar uma massa moldável.</li><li><b>Formar:</b> Molde os hambúrgueres com as mãos.</li><li><b>Grelhar:</b> Cozinhe numa frigideira antiaderente com um fio de azeite até dourarem de ambos os lados.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_LASANHA_COUVE_PENCA + "', '<h3>Ingredientes:</h3><ul><li>Folhas de couve penca escaldadas</li><li>Bolonhesa de lentilhas</li><li>Queijo vegan para gratinar</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Use as folhas de couve como se fossem a massa da lasanha, alternando com as lentilhas.</li><li><b>Assar:</b> Cubra com o queijo e leve ao forno por 20 min até estar bem quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_TEMPEH_PASTINACA_FORNO + "', '<h3>Ingredientes:</h3><ul><li>100 g de tempeh, pastinaca</li><li>Azeite, alecrim</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Leve tudo ao forno com temperos.</li><li><b>Servir:</b> A pastinaca caramelizada acompanha muito bem o tempeh.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_CARIL_BELUGA_ESPINAFRES + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de lentilhas beluga</li><li>Espinafres, leite de coco, caril</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza as lentilhas com o caril e leite de coco.</li><li><b>Finalizar:</b> Junte os espinafres no fim para murcharem apenas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_CROQUETES_FEIJAO_ARROZ + "', '<h3>Ingredientes:</h3><ul><li>Feijão, arroz, pão ralado</li><li>Temperos de ervas</li></ul><h3>Preparação:</h3><ol><li><b>Moldar:</b> Misture tudo e forme pequenos croquetes.</li><li><b>Cozinhar:</b> Frite ou leve ao forno até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_TARTE_CEBOLA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>Massa folhada, cebola caramelizada</li><li>Sálvia fresca</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Cubra a massa com a cebola e a sálvia.</li><li><b>Assar:</b> Leve ao forno quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_ALMONDEGAS_BOLOTA_PURE + "', '<h3>Ingredientes:</h3><ul><li>Almôndegas de bolota, puré de batata</li><li>Molho de ervas</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Cozinhe as almôndegas.</li><li><b>Servir:</b> Acompanhe com um puré cremoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_GNOCCHI_ESPINAFRES_NOZ + "', '<h3>Ingredientes:</h3><ul><li>Gnocchi, espinafres frescos</li><li>Nozes, manteiga vegan</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe tudo numa frigideira com manteiga.</li><li><b>Finalizar:</b> Polvilhe com nozes picadas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_ESPAGUETE_SARRACENO + "', '<h3>Ingredientes:</h3><ul><li>Esparguete de sarraceno, alho</li><li>Azeite, manjericão</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Prepare a massa.</li><li><b>Envolver:</b> Salteie com alho, azeite e manjericão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_TROUXAS_GALEGA_QUINOA + "', '<h3>Ingredientes:</h3><ul><li>Folhas de couve galega</li><li>Quinoa cozida, tomate</li></ul><h3>Preparação:</h3><ol><li><b>Escaldar:</b> Passe as folhas por água a ferver.</li><li><b>Rechear:</b> Envolva a quinoa nas folhas e coza ao vapor.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_BATATA_ROXA_HUMUS + "', '<h3>Ingredientes:</h3><ul><li>Batata-roxa assada</li><li>Humus de grão-de-bico</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse a batata.</li><li><b>Montar:</b> Recheie com uma colher generosa de humus.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_ESTUFADO_GRAO_REPOLHO + "', '<h3>Ingredientes:</h3><ul><li>Grão-de-bico, repolho cortado</li><li>Azeite, cebola</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe tudo em lume brando até estar tenro.</li><li><b>Servir:</b> Prato reconfortante de inverno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_POLENTA_FRITA_PORTOBELLO + "', '<h3>Ingredientes:</h3><ul><li>Polenta, cogumelo Portobello</li><li>Azeite</li></ul><h3>Preparação:</h3><ol><li><b>Fritar:</b> Grelhe a polenta e o cogumelo.</li><li><b>Servir:</b> Prato de textura contrastante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_QUICHE_NABO_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>Massa, nabo, alho-francês</li><li>Base de natas de soja</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte os vegetais à base líquida.</li><li><b>Assar:</b> Leve ao forno até dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_ESPETADAS_TEMPEH_CASTANHAS + "', '<h3>Ingredientes:</h3><ul><li>Cubos de tempeh, castanhas</li><li>Molho de soja</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar:</b> Alterne os ingredientes e grelhe.</li><li><b>Finalizar:</b> Pincele com molho de soja durante a cozedura.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_ARROZ_FORNO_LOMBARDA + "', '<h3>Ingredientes:</h3><ul><li>Arroz, couve lombarda</li><li>Azeite, alho</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Leve ao forno com o caldo até o arroz estar cozido.</li><li><b>Servir:</b> Prato nutritivo e simples.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_TOFU_LAGAREIRO_NOV + "', '<h3>Ingredientes:</h3><ul><li>Tofu em cubos, batatas a murro</li><li>Muito azeite, alho</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse tudo até estar estaladiço.</li><li><b>Regar:</b> Termine com o azeite quente e alho.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_CHILI_LENTILHAS_CACAU + "', '<h3>Ingredientes:</h3><ul><li>Lentilhas, cacau em pó, tomate</li><li>Especiarias picantes</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe as lentilhas com o tomate e o toque de cacau.</li><li><b>Servir:</b> Sabor profundo e intenso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_MIGAS_COUVE_PENCA + "', '<h3>Ingredientes:</h3><ul><li>Broa de milho, couve penca</li><li>Alho, azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Faça as migas com a couve e o alho.</li><li><b>Servir:</b> Acompanhamento clássico e reconfortante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_CRUMBLE_SALGADO_RAIZES + "', '<h3>Ingredientes:</h3><ul><li>Raízes diversas, farinha, azeite</li><li>Ervas frescas</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Cozinhe os vegetais cobertos com a farinha.</li><li><b>Dourar:</b> Leve ao forno até estalar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_WRAP_FEIJAO_FRADE + "', '<h3>Ingredientes:</h3><ul><li>Tortilha, feijão frade, espinafres</li><li>Humus</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Barre o wrap com humus e recheie.</li><li><b>Aquecer:</b> Grelhe rapidamente na chapa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_MASSA_TOMATE_AZEITONA + "', '<h3>Ingredientes:</h3><ul><li>Massa, molho de tomate, azeitonas</li><li>Manjericão</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Prepare a massa.</li><li><b>Envolver:</b> Junte o tomate e as azeitonas, terminando com manjericão.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_ESTUFADO_ERVILHAS_TOFU + "', '<h3>Ingredientes:</h3><ul><li>Ervilhas frescas, tofu em cubos</li><li>Cebola, cenoura</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe tudo em lume brando.</li><li><b>Servir:</b> Prato de cor verde vibrante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_BOLINHOS_ARROZ_GRAO + "', '<h3>Ingredientes:</h3><ul><li>Arroz cozido, grão-de-bico</li><li>Ervas aromáticas</li></ul><h3>Preparação:</h3><ol><li><b>Moldar:</b> Forme bolinhos com os ingredientes.</li><li><b>Dourar:</b> Leve ao forno ou frite em pouco azeite.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_NOV_JAN_EMPADAO_COGUMELOS_DOCE + "', '<h3>Ingredientes:</h3><ul><li>Cogumelos, puré de batata-doce</li><li>Cebola</li></ul><h3>Preparação:</h3><ol><li><b>Estufar:</b> Cozinhe os cogumelos.</li><li><b>Cobrir:</b> Cubra com o puré e leve ao forno.</li></ol>');");

        // ==========================================
// PEQUENOS-ALMOÇOS - DEZEMBRO (31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_RABANADA_FORNO_CANELA + "', '<h3>Ingredientes:</h3><ul><li>2 fatias grossas de pão integral de véspera</li><li>1 chávena de bebida de amêndoa, 1 pau de canela</li><li>Geleia de arroz e canela em pó</li><li>Casca de limão</li></ul><h3>Preparação:</h3><ol><li><b>Infusão:</b> Aqueça a bebida vegetal com o pau de canela e a casca de limão.</li><li><b>Demolhar:</b> Passe as fatias de pão pela infusão morna até estarem bem húmidas.</li><li><b>Assar:</b> Coloque num tabuleiro com papel vegetal e leve ao forno a 200°C por 15 min.</li><li><b>Finalizar:</b> Pincele com a geleia de arroz e polvilhe com canela. Sirva quentinho.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PAPA_AVEIA_NATAL_ESPECIARIAS + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de aveia</li><li>1 chávena de bebida de avelã</li><li>1 estrela de anis, 1 cravo-da-índia, 1 pau de canela</li><li>Amêndoas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a aveia na bebida de avelã com todas as especiarias em lume brando.</li><li><b>Aromatizar:</b> Deixe ferver até estar bem cremosa e aromática.</li><li><b>Servir:</b> Retire as especiarias inteiras e guarneça com as amêndoas crocantes.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_TORRADA_DOCE_GILA_NOZ + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de centeio e malte</li><li>2 colheres de sopa de doce de gila (caseiro)</li><li>1 mão cheia de nozes nacionais picadas</li><li>Canela</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Toste bem o pão de centeio.</li><li><b>Montar:</b> Barre uma camada generosa de doce de gila sobre as torradas quentes.</li><li><b>Finalizar:</b> Salpique com as nozes e uma pitada de canela. O sabor do Natal numa torrada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PANQUECA_GENGIBRE_MEL + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de sopa de farinha integral</li><li>1 colher de chá de gengibre fresco ralado</li><li>1 colher de chá de melaço ou mel de arroz</li><li>1/2 chávena de bebida vegetal e fermento</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha, o gengibre, o melaço e o líquido até obter um polme liso.</li><li><b>Cozinhar:</b> Faça as panqueques numa frigideira quente.</li><li><b>Servir:</b> Regue com um fio extra de mel de arroz. O gengibre ajuda a aquecer o corpo no inverno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_BOLO_CANECA_CHOCOLATE_LARANJA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de farinha de aveia, 1 de cacau</li><li>Raspa de 1/2 laranja e 2 colheres de sumo de laranja</li><li>1 colher de sopa de iogurte vegetal e fermento</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte os ingredientes secos, a raspa, o sumo e o iogurte na caneca.</li><li><b>Mexer:</b> Bata bem com um garfo até estar homogéneo.</li><li><b>Cozedura:</b> Leve ao microondas por 90 segundos. Um mimo de chocolate e citrinos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_WAFFLE_ALFARROBA_PASSAS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de massa de waffle (farinha de aveia + água)</li><li>2 colheres de sopa de farinha de alfarroba</li><li>1 colher de sopa de passas de uva</li><li>Pinhões para decorar</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a alfarroba na massa base e envolva as passas.</li><li><b>Tostar:</b> Cozinhe na máquina de waffles até estar estaladiça.</li><li><b>Finalizar:</b> Sirva com pinhões tostados por cima. A alfarroba substitui o chocolate com um sabor único.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PUDIM_CHIA_CLEMENTINA + "', '<h3>Ingredientes:</h3><ul><li>3 colheres de sopa de chia</li><li>Sumo de 2 clementinas e os seus gomos</li><li>100ml de leite de coco leve</li><li>Sementes de abóbora</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Hidrate a chia no sumo de clementina e leite de coco. Repouse por 1 hora.</li><li><b>Fruta:</b> Limpe os gomos de clementina de peles brancas.</li><li><b>Servir:</b> Disponha a fruta e as sementes sobre o pudim gelificado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_TOFU_MEXIDO_COUVES_BRUXELAS + "', '<h3>Ingredientes:</h3><ul><li>150g de tofu firme</li><li>6 couves-bruxelas cortadas em fatias muito finas</li><li>Cúrcuma, alho em pó, azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Frite as lâminas de couve-bruxelas em azeite até dourarem e ficarem crocantes.</li><li><b>Cozinhar:</b> Junte o tofu esmagado e a cúrcuma.</li><li><b>Finalizar:</b> Mexa bem até o tofu estar quente e temperado. Um pequeno-almoço verde e rico.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_CREPE_AVEIA_COMPOTA_PERA + "', '<h3>Ingredientes:</h3><ul><li>1 crepe de aveia (farinha + água)</li><li>2 colheres de sopa de compota de pera rústica</li><li>Amêndoas picadas</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Faça o crepe na frigideira.</li><li><b>Rechear:</b> Barre com a compota de pera ainda morna.</li><li><b>Dobrar:</b> Dobre em quatro e polvilhe com as amêndoas para dar crocância.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_MUFFIN_BANANA_ESPECIARIAS + "', '<h3>Ingredientes:</h3><ul><li>2 bananas muito maduras</li><li>1 chávena de aveia, 1 colher de chá de canela</li><li>1 pitada de noz-moscada e cravinho moído</li><li>Fermento e água q.b.</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Esmague as bananas e junte os secos. Adicione água até ter consistência de bolo.</li><li><b>Formas:</b> Encha formas de queque.</li><li><b>Assar:</b> Leve ao forno a 180°C por 20 min. O aroma de especiarias inundará a cozinha.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_BATIDO_QUENTE_AVELA_CACAU + "', '<h3>Ingredientes:</h3><ul><li>1 e 1/2 chávena de bebida de avelã</li><li>1 colher de sopa de cacau puro, 1 de mel de arroz</li><li>1/2 colher de chá de extrato de baunilha</li></ul><h3>Preparação:</h3><ol><li><b>Aquecer:</b> Leve a bebida de avelã ao lume até estar bem quente.</li><li><b>Misturar:</b> No liquidificador, bata o leite com o cacau, o doce e a baunilha.</li><li><b>Beber:</b> Sirva com espuma por cima e um pouco de cacau polvilhado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PAPA_CENTEIO_MACA_REINETA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de centeio</li><li>1 maçã Reineta ralada</li><li>1 chávena de água, canela e casca de limão</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza a farinha na água com a casca de limão e canela por 5 min.</li><li><b>Fruta:</b> Junte a maçã Reineta ralada (ácida e aromática) e envolva bem.</li><li><b>Servir:</b> Coma quente. A Reineta desfaz-se nas papas criando uma textura única.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_TORRADA_CREME_AMENDOIM_CACAU + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão rústico</li><li>1 colher de manteiga de amendoim</li><li>1 colher de chá de nibs de cacau ou cacau em pó</li><li>Fatias de banana</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Prepare as torradas.</li><li><b>Barrar:</b> Espalhe a manteiga de amendoim.</li><li><b>Finalizar:</b> Disponha a banana e polvilhe com o cacau. Um clássico energético.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_SCONES_NATAL_PASSAS_NOZ + "', '<h3>Ingredientes:</h3><ul><li>1 e 1/2 chávena de farinha com fermento</li><li>1/2 chávena de bebida vegetal</li><li>1/2 chávena de mistura de passas e nozes picadas</li><li>Erva-doce</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Junte todos os ingredientes até ter uma massa que se despegue das mãos.</li><li><b>Formar:</b> Faça pequenas bolas rústicas.</li><li><b>Assar:</b> Leve ao forno a 200°C por 12-15 min. Coma-os ainda mornos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_BRUSCHETTA_COZIDO_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão alentejano torrada</li><li>Sobras de vegetais do cozido (couve, cenoura, nabo)</li><li>Azeite e alho</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Aqueça os vegetais do cozido picados numa frigideira com alho e azeite.</li><li><b>Montar:</b> Disponha sobre o pão acabado de torrar.</li><li><b>Finalizar:</b> Regue com um fio de azeite extra e pimenta preta. Aproveitamento delicioso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PAPA_PAINCO_COCO_LARANJA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de flocos de painço</li><li>1 chávena de leite de coco e sumo de 1/2 laranja</li><li>Raspa de laranja e coco ralado</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Coza o painço no leite de coco e sumo de laranja até estar macio.</li><li><b>Aromatizar:</b> Junte a raspa de laranja no final.</li><li><b>Servir:</b> Polvilhe com coco ralado. O painço é muito leve para começar o dia.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_GRANOLA_INVERNO_IOGURTE + "', '<h3>Ingredientes:</h3><ul><li>1 taça de iogurte de soja natural</li><li>3 colheres de sopa de granola crocante</li><li>1 colher de sementes de cânhamo</li><li>Frutos vermelhos congelados (aquecidos)</li></ul><h3>Preparação:</h3><ol><li><b>Fruta:</b> Aqueça os frutos vermelhos no microondas até criarem um molho.</li><li><b>Montar:</b> Coloque o iogurte, a granola e as sementes na taça.</li><li><b>Finalizar:</b> Verta o molho quente de frutos por cima e sirva.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_BATIDO_TANGERINA_LINHACA + "', '<h3>Ingredientes:</h3><ul><li>Sumo de 3 tangerinas frescas</li><li>1 banana madura</li><li>1 colher de sopa de sementes de linhaça moída</li><li>1 rodela de gengibre</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Coloque todos os ingredientes no liquidificador.</li><li><b>Processar:</b> Bata até estar bem homogéneo e espumoso.</li><li><b>Beber:</b> Consuma de imediato para um reforço de Vitamina C.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_GALETTE_SARRACENO_REINETA + "', '<h3>Ingredientes:</h3><ul><li>Massa de trigo sarraceno rústica</li><li>1 maçã Reineta em fatias</li><li>Canela e 1 colher de mel de urze</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Coloque a maçã sobre a massa de sarraceno estendida.</li><li><b>Dobra:</b> Feche as bordas de forma rústica.</li><li><b>Assar:</b> Leve ao forno a 190°C até a massa estar estaladiça e a maçã cozida.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_OVO_COCOTE_TRUFA_FORNO + "', '<h3>Ingredientes:</h3><ul><li>1 ovo biológico</li><li>1 colher de sopa de natas de soja</li><li>Gotas de azeite trufado</li><li>Sal e pimenta preta</li></ul><h3>Preparação:</h3><ol><li><b>Ramequim:</b> Coloque as natas no fundo de um ramequim, parta o ovo por cima.</li><li><b>Cozedura:</b> Leve ao forno a 180°C em banho-maria por 10 min.</li><li><b>Finalizar:</b> Retire e adicione o azeite trufado e pimenta. Coma com tiras de pão torrado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_BARRINHA_AVEIA_FRUTOS_SECOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de aveia, 1/2 de mistura de frutos secos</li><li>2 colheres de sopa de melaço de cana</li><li>1/2 maçã ralada</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Envolva tudo numa taça até ter uma massa pegajosa.</li><li><b>Pressionar:</b> Coloque numa forma quadrada e alise bem.</li><li><b>Assar:</b> Leve ao forno 15 min. Deixe arrefecer totalmente antes de cortar em barras.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_TORRADA_REQUEIJAO_TOMILHO + "', '<h3>Ingredientes:</h3><ul><li>2 fatias de pão de malte</li><li>1/2 chávena de requeijão de amêndoa</li><li>Tomilho fresco e sal grosso</li></ul><h3>Preparação:</h3><ol><li><b>Torrar:</b> Prepare as torradas bem quentes.</li><li><b>Barrar:</b> Coloque colheradas de requeijão vegetal por cima.</li><li><b>Aromatizar:</b> Polvilhe com tomilho fresco e uma pedra de sal. Simples e sofisticado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_SMOOTHIE_BOWL_ESPINAFRE_PERA + "', '<h3>Ingredientes:</h3><ul><li>1 mão cheia de espinafres baby</li><li>1 pera rocha madura</li><li>1/2 chávena de iogurte natural</li><li>Topping: Granola de chocolate</li></ul><h3>Preparação:</h3><ol><li><b>Triturar:</b> Bata os espinafres com a pera e o iogurte até ficar um creme verde liso.</li><li><b>Servir:</b> Verta para uma taça larga.</li><li><b>Decorar:</b> Adicione a granola por cima e coma à colher.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PAPA_SARRACENO_MACA_ASSADA + "', '<h3>Ingredientes:</h3><ul><li>1/2 chávena de farinha de trigo sarraceno</li><li>1 maçã assada no forno (sobra)</li><li>1 chávena de água e canela</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Faça as papas de sarraceno em água com canela.</li><li><b>Misturar:</b> Junte a polpa da maçã assada e envolva para que as papas fiquem doces e cremosas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_WRAP_QUENTE_AMENDOA_MAÇA + "', '<h3>Ingredientes:</h3><ul><li>1 tortilha integral</li><li>1 colher de manteiga de amêndoa</li><li>1/2 maçã fatiada muito fina</li><li>Canela</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Barre a tortilha com a manteiga, disponha a maçã e polvilhe canela.</li><li><b>Dobrar:</b> Enrole bem apertado.</li><li><b>Aquecer:</b> Grelhe 1 min de cada lado na frigideira para a maçã amolecer e o wrap ficar estaladiço.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_BOLACHAS_BOLOTA_GINGERBREAD + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de farinha de bolota</li><li>1 colher de sopa de gengibre em pó e canela</li><li>1/2 chávena de xarope de tâmaras</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture os ingredientes até ter uma massa maleável.</li><li><b>Moldar:</b> Use cortadores de Natal (bonecos ou estrelas).</li><li><b>Assar:</b> Leve ao forno 10 min a 180°C. Deliciosas e saudáveis.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_TACA_KEFIR_ARANDOS_AVELA + "', '<h3>Ingredientes:</h3><ul><li>1 taça de kefir vegetal</li><li>1/4 chávena de arandos secos (cranberries)</li><li>1 mão cheia de avelãs torradas</li></ul><h3>Preparação:</h3><ol><li><b>Misturar:</b> Coloque o kefir numa taça.</li><li><b>Finalizar:</b> Adicione os arandos e as avelãs. Um pequeno-almoço probiótico e crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PUDIM_LINHACA_KAKI + "', '<h3>Ingredientes:</h3><ul><li>2 colheres de sopa de sementes de linhaça moída</li><li>Polpa de 1/2 dióspiro kaki maduro</li><li>1/2 chávena de bebida vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Hidrate a linhaça na bebida vegetal por 20 min até espessar.</li><li><b>Fruta:</b> Envolva a polpa de kaki delicadamente.</li><li><b>Consumir:</b> Coma fresco como um pudim matinal rico em fibras.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_BRUSCHETTA_SHIITAKE_ALECRIM + "', '<h3>Ingredientes:</h3><ul><li>1 fatia de pão de malte torrada</li><li>150g de cogumelos Shiitake fatiados</li><li>Alecrim fresco e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe os cogumelos com alecrim em azeite até dourarem.</li><li><b>Servir:</b> Disponha sobre o pão e regue com um fio de azeite extra.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_PANQUECA_CASTANHA_DOCE_ABOBORA + "', '<h3>Ingredientes:</h3><ul><li>4 colheres de farinha de castanha</li><li>1/2 chávena de puré de abóbora</li><li>1 ovo (ou linhaça)</li><li>Canela e mel de arroz</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Misture a farinha, o puré e o ovo.</li><li><b>Cozinhar:</b> Faça as panquecas na frigideira e sirva com mel de arroz.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_PEQ_TACA_IOGURTE_TANGERINA_PINHAO + "', '<h3>Ingredientes:</h3><ul><li>1 iogurte vegetal</li><li>2 tangerinas em gomos</li><li>1 colher de pinhões nacionais</li></ul><h3>Preparação:</h3><ol><li><b>Montar:</b> Coloque o iogurte numa taça.</li><li><b>Finalizar:</b> Adicione os gomos de tangerina e os pinhões tostados.</li></ol>');");

        // ==========================================
// ALMOÇOS - DEZEMBRO (31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_ROUPA_VELHA_VEGAN + "', '<h3>Ingredientes:</h3><ul><li>Sobras de vegetais cozidos (batata, couve, cenoura, nabo)</li><li>1 chávena de grão-de-bico cozido</li><li>4 dentes de alho picados</li><li>Azeite virgem extra em abundância</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Corte as sobras de legumes em pedaços pequenos.</li><li><b>Saltear:</b> Numa frigideira larga, doure o alho em bastante azeite. Junte os legumes e o grão.</li><li><b>Finalizar:</b> Deixe saltear em lume alto, mexendo sempre, até os legumes estarem bem quentes e ligeiramente tostados. Sirva com um fio de azeite cru.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_ASSADO_NATAL_SEITAN + "', '<h3>Ingredientes:</h3><ul><li>400g de seitan em fatias grossas</li><li>12 batatas pequenas para assar</li><li>12 cebolinhas pérola</li><li>Vinho branco, alecrim, louro e pimentão doce</li><li>Azeite virgem extra e sal</li></ul><h3>Preparação:</h3><ol><li><b>Marinar:</b> Tempere o seitan com alho, louro e pimentão doce.</li><li><b>Assar:</b> Disponha o seitan, as batatas (esmurradas) e as cebolinhas num tabuleiro.</li><li><b>Temperar:</b> Regue com azeite e vinho branco. Junte o alecrim.</li><li><b>Forno:</b> Leve ao forno a 200°C por 40 min até estar tudo dourado e apetitoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_FEIJOADA_TRANS_FEIJOCAS + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijocas cozidas</li><li>200g de tofu fumado em cubos</li><li>1/2 couve lombarda em tiras</li><li>Cenoura, polpa de tomate, cominhos e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Refogue a cebola e alho em azeite. Junte o tofu fumado e a couve.</li><li><b>Estufar:</b> Adicione a polpa de tomate e um pouco de água. Deixe a couve amolecer.</li><li><b>Finalizar:</b> Junte as feijocas e deixe apurar em lume brando por 15 min. Sirva com arroz de alho.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_ARROZ_FORNO_PASSA_PINHAO + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz agulha</li><li>1/4 chávena de passas de uva, 1/4 de pinhões</li><li>1 cebola pequena, 1 pau de canela</li><li>Caldo de legumes quente e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Refogue a cebola em azeite num tacho que possa ir ao forno.</li><li><b>Arroz:</b> Junte o arroz, as passas e os pinhões. Envolva bem.</li><li><b>Assar:</b> Adicione o caldo a ferver (proporção 1:2) e o pau de canela. Leve ao forno a 200°C por 15-18 min.</li><li><b>Finalizar:</b> Retire a canela e solte o arroz com um garfo antes de servir.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_TOFU_BROA_COUVE_TRONCHUDA + "', '<h3>Ingredientes:</h3><ul><li>300g de tofu firme</li><li>1 molho de couve tronchuda (ou galega)</li><li>200g de broa de milho esfarelada</li><li>Azeite, alho e louro</li></ul><h3>Preparação:</h3><ol><li><b>Couve:</b> Salteie a couve picada com alho e azeite até estar tenra.</li><li><b>Tofu:</b> Grelhe fatias de tofu temperadas com limão.</li><li><b>Gratinar:</b> Coloque a couve num pirex, o tofu por cima e cubra com a broa misturada com alho e azeite. Leve ao forno a dourar.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_RANCHO_WINTER_VERSION + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de grão-de-bico, 1 de massa macarrão</li><li>2 batatas, 1 nabo, 1/4 couve portuguesa</li><li>Colorau, cebola, alho e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Cozedura:</b> Coza os legumes em água com sal e colorau.</li><li><b>Massa:</b> Junte a massa a meio da cozedura.</li><li><b>Finalizar:</b> Adicione o grão e retifique os temperos. Sirva como um tacho rico e reconfortante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_RISOTO_ABOBORA_NOZ_MOSCADA + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz para risoto (Arbório)</li><li>2 chávenas de puré de abóbora assada</li><li>Caldo de legumes, 1 cebola, noz-moscada</li><li>Azeite virgem</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Refogue a cebola, junte o arroz e vá deitando o caldo aos poucos.</li><li><b>Cremar:</b> Quando o arroz estiver quase pronto, envolva o puré de abóbora.</li><li><b>Finalizar:</b> Tempere com bastante noz-moscada e uma colher de manteiga vegetal.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_EMPADAO_LENTILHAS_PURE_DOCE + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de lentilhas castanhas estufadas</li><li>800g de puré de batata-doce laranja</li><li>Cebola, alho, polpa de tomate e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Coloque as lentilhas estufadas no fundo de um pirex.</li><li><b>Cobertura:</b> Cubra com o puré de batata-doce cremoso (feito com um pingo de leite de coco).</li><li><b>Assar:</b> Leve ao forno a 200°C por 15 min até a superfície estar firme e dourada.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_CARIL_INVERNO_COUVE_FLOR + "', '<h3>Ingredientes:</h3><ul><li>1 couve-flor média em floretes</li><li>1 lata de leite de coco</li><li>2 colheres de sopa de caril em pó</li><li>Gengibre, cebola, alho e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estufe a couve-flor no leite de coco com os temperos de caril.</li><li><b>Apurar:</b> Cozinhe em lume brando até a couve-flor estar tenra mas inteira.</li><li><b>Finalizar:</b> Polvilhe com muitos coentros frescos picados. Sirva com arroz basmati.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_MASSA_FORNO_COGUMELOS_TRUFA + "', '<h3>Ingredientes:</h3><ul><li>300g de massa curta (ex: penne)</li><li>400g de cogumelos variados</li><li>1 pacote de natas de aveia (200ml)</li><li>Azeite trufado e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Salteie os cogumelos com alho em azeite.</li><li><b>Misturar:</b> Envolva a massa cozida com os cogumelos e as natas.</li><li><b>Assar:</b> Coloque num tabuleiro e leve ao forno 10 min. Finalize com gotas de azeite trufado e salsa.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_COZIDO_MINHOTO_VEGAN + "', '<h3>Ingredientes:</h3><ul><li>Batata, cenoura, nabo, couve galega</li><li>Feijão branco cozido</li><li>Chouriço e morcela de soja</li><li>Azeite e hortelã</li></ul><h3>Preparação:</h3><ol><li><b>Cozer:</b> Leve todos os ingredientes a cozer em água e sal.</li><li><b>Arroz:</b> Utilize o caldo para fazer um arroz de forno.</li><li><b>Servir:</b> Disponha os legumes, feijão e enchidos fatiados numa travessa grande.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_LASANHA_COGUMELOS_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>Folhas de lasanha</li><li>3 alhos-franceses grandes</li><li>400g de cogumelos fatiados</li><li>Molho bechamel de soja</li></ul><h3>Preparação:</h3><ol><li><b>Recheio:</b> Salteie o alho-francês e os cogumelos até estarem macios.</li><li><b>Montar:</b> Alterne camadas de massa, o refogado de vegetais e bechamel.</li><li><b>Assar:</b> Leve ao forno por 30 min até a massa estar cozida e o topo dourado.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_ALMONDEGAS_LENTILHAS_MOLHO + "', '<h3>Ingredientes:</h3><ul><li>Almôndegas de lentilhas castanhas</li><li>500ml de molho de tomate rústico</li><li>Páprica fumada e alho</li></ul><h3>Preparação:</h3><ol><li><b>Preparar:</b> Cozinhe as almôndegas no forno por 15 min.</li><li><b>Estufar:</b> Junte as almôndegas ao molho de tomate e deixe apurar 10 min.</li><li><b>Acompanhar:</b> Sirva com esparguete integral ou puré de batata.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_TARTE_RUSTICA_COUVE_BRUXELAS + "', '<h3>Ingredientes:</h3><ul><li>1 base de massa quebrada</li><li>12 couves-bruxelas cortadas ao meio</li><li>1/2 chávena de nozes picadas</li><li>Natas de soja e queijo vegan</li></ul><h3>Preparação:</h3><ol><li><b>Couve:</b> Salteie as couves-bruxelas em azeite por 5 min.</li><li><b>Montar:</b> Coloque-as sobre a massa, junte as nozes e cubra com as natas.</li><li><b>Assar:</b> Leve ao forno a 190°C por 20 min até a massa estar crocante.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_GNOCCHI_CASTANHA_SALVIA + "', '<h3>Ingredientes:</h3><ul><li>500g de gnocchi de castanha (ou batata)</li><li>1 chávena de castanhas cozidas</li><li>Manteiga vegetal e folhas de sálvia fresca</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Doure as castanhas e a sálvia na manteiga vegetal até estarem perfumadas.</li><li><b>Misturar:</b> Junte o gnocchi cozido e envolva bem. Sirva com pimenta preta moída na hora.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_MIGAS_NATAL_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>300g de broa de milho</li><li>400g de cogumelos silvestres</li><li>Muito alho, azeite virgem extra e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Broa:</b> Esfarele a broa de milho.</li><li><b>Saltear:</b> Frite os cogumelos com muito alho em azeite.</li><li><b>Misturar:</b> Junte a broa e envolva até ficar bem tostada e integrada com os cogumelos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_STIR_FRY_TEMPEH_GALEGA + "', '<h3>Ingredientes:</h3><ul><li>200g de tempeh em cubos</li><li>1 molho de couve galega fatiada muito fina</li><li>Molho de soja, gengibre e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Tempeh:</b> Grelhe o tempeh com gengibre até estar crocante.</li><li><b>Wok:</b> Junte a couve galega e salteie apenas 2 min para manter a cor vibrante.</li><li><b>Finalizar:</b> Tempere com soja e sirva com arroz basmati.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_BURRITO_QUENTE_INVERNO + "', '<h3>Ingredientes:</h3><ul><li>Tortilhas grandes</li><li>Feijão encarnado estufado</li><li>Arroz integral e vegetais de raiz assados</li><li>Molho picante (opcional)</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Coloque o feijão, arroz e vegetais no centro da tortilha.</li><li><b>Fechar:</b> Enrole firmemente.</li><li><b>Grelhar:</b> Aqueça na frigideira para selar e servir bem quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_TACOS_JACKFRUIT_ESPECIARIAS + "', '<h3>Ingredientes:</h3><ul><li>Jackfruit (em conserva) desfiada</li><li>Especiarias: páprica, cominhos, chili</li><li>Mini tortilhas, lima e coentros</li></ul><h3>Preparação:</h3><ol><li><b>Jackfruit:</b> Salteie a jackfruit com as especiarias até parecer carne desfiada.</li><li><b>Montar:</b> Recheie as tortilhas aquecidas.</li><li><b>Finalizar:</b> Sirva com bastantes gotas de lima fresca e coentros.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_COUSCOUS_NATAL_FRUTOS_SECOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de cuscuz grosso</li><li>1/2 chávena de alperces secos e passas</li><li>1/2 chávena de nozes e pinhões picados</li><li>Hortelã fresca</li></ul><h3>Preparação:</h3><ol><li><b>Hidratar:</b> Prepare o cuscuz com caldo vegetal quente.</li><li><b>Misturar:</b> Solte os grãos e junte os frutos secos e desidratados picados.</li><li><b>Servir:</b> Um acompanhamento festivo e cheio de texturas.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_FEIJAO_FRADE_GRELOS_TOFU + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de feijão frade cozido</li><li>1 molho de grelos cozidos</li><li>200g de tofu em cubos</li><li>Azeite e alho abundante</li></ul><h3>Preparação:</h3><ol><li><b>Tofu:</b> Frite o tofu com alho.</li><li><b>Saltear:</b> Junte os grelos e o feijão.</li><li><b>Finalizar:</b> Envolva bem com azeite e sirva quente.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_MARMITA_FORNO_RAIZES + "', '<h3>Ingredientes:</h3><ul><li>Pastinaca, cenoura, nabo e batata</li><li>Lentilhas beluga cozidas</li><li>Alecrim e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Leve as raízes ao forno com alecrim por 30 min.</li><li><b>Finalizar:</b> Junte as lentilhas e sirva na marmita.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_CANELONES_ABOBORA_REQUEIJAO + "', '<h3>Ingredientes:</h3><ul><li>Canelones, puré de abóbora</li><li>Requeijão vegan, molho tomate</li></ul><h3>Preparação:</h3><ol><li><b>Rechear:</b> Encha os canelones com abóbora e requeijão.</li><li><b>Assar:</b> Cubra com tomate e leve ao forno 25 min.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_CHILI_VEGAN_INVERNO + "', '<h3>Ingredientes:</h3><ul><li>Feijão preto, lentilhas, tomate</li><li>Cacau puro, chili e cominhos</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Estufe tudo em lume brando. O cacau dá profundidade ao molho.</li><li><b>Servir:</b> Com arroz integral.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_XAREM_INVERNO_PLEUROTUS + "', '<h3>Ingredientes:</h3><ul><li>Farinha de milho, caldo legumes</li><li>Cogumelos Pleurotus, alho e salsa</li></ul><h3>Preparação:</h3><ol><li><b>Xarém:</b> Prepare as papas de milho.</li><li><b>Saltear:</b> Frite os cogumelos com alho.</li><li><b>Servir:</b> Disponha os cogumelos sobre o xarém cremoso.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_ESPAGUETE_ALHO_AZEITE_AVELA + "', '<h3>Ingredientes:</h3><ul><li>250g de esparguete de trigo integral</li><li>1/2 chávena de avelãs nacionais (tostadas e picadas grosseiramente)</li><li>4 dentes de alho grandes (laminados finamente)</li><li>1/2 chávena de azeite virgem extra</li><li>Um punhado de salsa fresca picada</li><li>Uma pitada de flocos de malagueta (opcional)</li><li>Flor de sal e pimenta preta</li></ul><h3>Preparação:</h3><ol><li><b>Massa:</b> Coza o esparguete em água abundante com sal até estar al dente. Reserve uma pequena caneca da água da cozedura antes de escorrer.</li><li><b>Infusão:</b> Numa frigideira larga, coloque o azeite e o alho laminado ainda em frio. Ligue o lume médio e deixe o alho dourar suavemente para aromatizar o azeite sem queimar.</li><li><b>Saltear:</b> Adicione as avelãs picadas e a malagueta. Deixe fritar por 1 minuto.</li><li><b>Envolver:</b> Junte a massa escorrida à frigideira e adicione um pouco da água da cozedura reservada. Envolva vigorosamente para o molho emulsionar.</li><li><b>Finalizar:</b> Desligue o lume, junte a salsa picada e retifique os temperos. Sirva de imediato com um fio de azeite extra.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_TORTILHA_FORNO_BATATA_ALHO + "', '<h3>Ingredientes:</h3><ul><li>3 batatas médias (cortadas em cubos pequenos)</li><li>2 chávenas de espinafres frescos baby</li><li>2 dentes de alho picados</li><li>1 chávena de farinha de grão-de-bico</li><li>1 e 1/4 chávena de água</li><li>1/2 colher de chá de cúrcuma e uma pitada de sal negro (Kala Namak)</li><li>Azeite virgem extra e sal</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar Batata:</b> Salteie os cubos de batata numa frigideira com azeite até estarem dourados e macios. No final, junte o alho e os espinafres apenas para murcharem.</li><li><b>Massa:</b> Numa taça, bata a farinha de grão com a água, a cúrcuma e o sal até obter um creme liso (estilo ovo batido).</li><li><b>Misturar:</b> Envolva os legumes salteados na massa de grão.</li><li><b>Assar:</b> Verta o preparado para um pirex de forno redondo (untado). Leve ao forno a 180°C por 20-25 minutos até o centro estar firme.</li><li><b>Servir:</b> Deixe repousar 5 minutos antes de cortar em fatias.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_QUICHE_SEM_MASSA_PENCA + "', '<h3>Ingredientes:</h3><ul><li>2 chávenas de couve penca (cortada em tiras finas)</li><li>1 alho-porro grande (apenas a parte branca, em rodelas)</li><li>250g de tofu firme (esmagado)</li><li>200ml de natas de soja ou aveia</li><li>2 colheres de sopa de farinha de grão-de-bico</li><li>Noz-moscada, sal e pimenta preta</li><li>Azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Salteie o alho-porro e a couve penca em azeite até estarem bem macios. Tempere com sal e pimenta.</li><li><b>Creme:</b> No liquidificador, triture o tofu com as natas vegetais, a farinha de grão e a noz-moscada até obter um creme espesso.</li><li><b>Combinar:</b> Numa taça, envolva os legumes no creme de tofu.</li><li><b>Assar:</b> Deite a mistura numa forma de tarte (ou pirex) untada. Leve ao forno a 190°C por cerca de 30 minutos até a superfície estar dourada e o interior firme.</li><li><b>Finalizar:</b> Sirva morna como um almoço leve e nutritivo.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_SEITAN_PIMENTA_PRETA + "', '<h3>Ingredientes:</h3><ul><li>400g de seitan firme (fatiado em bifes)</li><li>2 colheres de sopa de pimenta preta em grão (esmagada grosseiramente)</li><li>200ml de bebida de soja (sem açúcar) ou natas vegetais</li><li>1 colher de sopa de mostarda de Dijon</li><li>2 dentes de alho esmagados</li><li>50ml de vinho branco</li><li>Azeite e sal</li></ul><h3>Preparação:</h3><ol><li><b>Grelhar Seitan:</b> Doure os bifes de seitan em azeite bem quente de ambos os lados. Retire e reserve.</li><li><b>Deglacear:</b> Na mesma frigideira, junte o alho e a pimenta esmagada. Verta o vinho branco e deixe evaporar o álcool.</li><li><b>Molho:</b> Baixe o lume e adicione a bebida de soja e a mostarda. Mexa bem para integrar os sucos da carne vegetal.</li><li><b>Apurar:</b> Reintroduza o seitan na frigideira e deixe o molho engrossar por 3-5 minutos até ficar cremoso e envolver bem os bifes.</li><li><b>Servir:</b> Acompanhe com batata assada ou legumes ao vapor.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_ARROZ_MALANDRO_GRAO_TOMATE + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de arroz carolino (ou agulha)</li><li>2 chávenas de grão-de-bico cozido</li><li>3 tomates maduros picados (com pele e sementes)</li><li>1 cebola pequena e 2 dentes de alho picados</li><li>1 pimento verde pequeno em cubos</li><li>3 chávenas de caldo de legumes quente</li><li>Um punhado de hortelã fresca</li><li>Azeite, sal e pimentão doce</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Faça um refogado com cebola, alho, pimento e o pimentão doce em azeite. Junte o tomate e deixe cozinhar até se desfazer.</li><li><b>Arroz:</b> Adicione o arroz e envolva-o bem no refogado por 1 minuto.</li><li><b>Cozinhar:</b> Verta o caldo de legumes quente e o grão-de-bico. Tempere com sal.</li><li><b>Apurar:</b> Cozinhe em lume médio por 12-15 minutos. O arroz deve manter bastante caldo (malandrinho).</li><li><b>Finalizar:</b> Retire do lume e junte imediatamente a hortelã fresca picada à mão. Tape por 2 minutos antes de servir para o aroma perfumar o arroz.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_ALM_BATATA_DOCE_FORNO_LENTILHAS + "', '<h3>Ingredientes:</h3><ul><li>2 batatas-doces grandes (inteiras)</li><li>1 e 1/2 chávena de lentilhas castanhas cozidas</li><li>1 cebola pequena e 1 cenoura ralada</li><li>1/2 chávena de polpa de tomate</li><li>1 colher de chá de alecrim fresco picado</li><li>Azeite, sal e uma pitada de canela</li></ul><h3>Preparação:</h3><ol><li><b>Assar Batata:</b> Lave bem as batatas e leve-as ao forno a 200°C por 45-50 min até estarem bem macias por dentro.</li><li><b>Estufar Lentilhas:</b> Entretanto, faça um refogado com cebola e cenoura. Junte as lentilhas, o tomate, o alecrim e a canela. Deixe apurar em lume brando até o molho estar espesso e seco.</li><li><b>Rechear:</b> Retire as batatas do forno, abra-as ao meio longitudinalmente e esmague ligeiramente a polpa com um garfo.</li><li><b>Montar:</b> Distribua generosamente o estufado de lentilhas dentro das batatas.</li><li><b>Finalizar:</b> Leve ao forno por mais 5-10 minutos para gratinar ligeiramente. Decore com mais alecrim fresco e sirva.</li></ol>');");

        // ==========================================
// JANTARES - DEZEMBRO (31 DIAS)
// ==========================================

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_JAN_TOFU_ESPIRITUAL_NATAL + "', '<h3>Ingredientes:</h3><ul><li>300g de tofu firme esmagado</li><li>2 cenouras raladas, 1 cebola</li><li>1 fatia de pão de forma integral demolhada em bebida vegetal</li><li>Azeite, alho, louro e azeitonas pretas</li></ul><h3>Preparação:</h3><ol><li><b>Refogado:</b> Estufe a cebola, o alho e a cenoura em azeite. Junte o tofu e envolva bem.</li><li><b>Misturar:</b> Adicione o pão demolhado e mexa até criar uma consistência cremosa.</li><li><b>Gratinar:</b> Coloque num pirex, decore com azeitonas e leve ao forno a dourar. Uma versão vegetal do clássico Bacalhau Espiritual.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_JAN_POLENTA_INVERNO_COGUMELOS + "', '<h3>Ingredientes:</h3><ul><li>1 chávena de polenta cremosa</li><li>400g de cogumelos variados</li><li>2 dentes de alho, tomilho e alecrim</li><li>Azeite virgem extra</li></ul><h3>Preparação:</h3><ol><li><b>Cozinhar:</b> Prepare a polenta em caldo de legumes até estar bem macia.</li><li><b>Saltear:</b> Salteie os cogumelos com as ervas aromáticas e muito alho em azeite.</li><li><b>Servir:</b> Verta os cogumelos e o seu molho sobre a polenta numa taça de inverno.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_JAN_BATATA_DOCE_RECHEADA_INVERNO + "', '<h3>Ingredientes:</h3><ul><li>2 batatas-doces assadas</li><li>1 chávena de feijão preto estufado</li><li>Coentros, lima e molho de iogurte vegetal</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Asse as batatas até estarem muito tenras.</li><li><b>Rechear:</b> Abra a batata a meio e recheie com o feijão quente.</li><li><b>Finalizar:</b> Regue com molho de iogurte, sumo de lima e coentros frescos.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_JAN_EMPADAO_COUVE_FLOR_GRAO + "', '<h3>Ingredientes:</h3><ul><li>1 couve-flor média (puré)</li><li>2 chávenas de grão-de-bico cozido</li><li>Cebola, alho, polpa de tomate e açafrão</li></ul><h3>Preparação:</h3><ol><li><b>Base:</b> Estufe o grão com tomate e especiarias. Coloque no fundo do tabuleiro.</li><li><b>Puré:</b> Triture a couve-flor cozida com um pouco de açafrão para dar cor.</li><li><b>Assar:</b> Cubra o grão com o puré e leve ao forno por 15 min.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_JAN_ABOBORA_FORNO_ESPECIARIAS + "', '<h3>Ingredientes:</h3><ul><li>Fatias de abóbora manteiga</li><li>Sementes de abóbora e girassol</li><li>Canela, gengibre em pó e azeite</li></ul><h3>Preparação:</h3><ol><li><b>Assar:</b> Leve as fatias de abóbora ao forno temperadas com as especiarias e azeite.</li><li><b>Finalizar:</b> Quando estiverem caramelizadas, polvilhe com as sementes tostadas. Um jantar leve e aromático.</li></ol>');");

        db.execSQL("INSERT OR REPLACE INTO " + TABLE_RECIPES + " VALUES('" + MealConstants.PT_DEZ_JAN_FRITTATA_INVERNO_ALHO_PORRO + "', '<h3>Ingredientes:</h3><ul><li>2 alhos-franceses grandes</li><li>1 chávena de farinha de grão batida com água</li><li>Cúrcuma e pimenta preta</li></ul><h3>Preparação:</h3><ol><li><b>Saltear:</b> Cozinhe o alho-francês em rodelas até caramelizar.</li><li><b>Misturar:</b> Junte o alho-francês à base de grão temperada.</li><li><b>Cozinhar:</b> Deite numa frigideira, tape e deixe cozer em lume brando até estar firme.</li></ol>');");

